import type { MeaningPack } from '../../types';

export const teKirtana: MeaningPack = {
  lang: 'te',
  texts: {
    'tiruppavai': {
      summary: 'మార్గళి వ్రతం కోసం ఆండాళ్ రచించిన ముప్పై తమిళ గీతాలు. ఆయ్‌ప్పాడి కన్యలు తెల్లవారకముందే ఒకరినొకరు లేపుకొని, నందగోపుని ఇంటికి వెళ్ళి, కృష్ణుణ్ణి నప్పిన్నైని లేపి, “పఱై” అంటే ఆయన సేవను కోరుతారు. మార్గళి నెలలో రోజుకు ఒక పాశురం పాడతారు; ముప్పైయ్యవది రచయిత పేరునూ ఫలాన్నీ చెబుతుంది.',
      verses: {
        '0.0': 'హంసలతో నిండిన పొలాలున్న శ్రీవిల్లిపుత్తూరు ఆండాళ్‌ను స్మరించు. రంగనాథునికి తిరుప్పావై పద్యాలను మధురంగా పాడి, పాటల మాలను, తాను ధరించిన పూలమాలను ఆయనకు సమర్పించింది ఆమె.',
        '0.1': 'తాను ధరించిన మాలను ఇచ్చిన తేజోమయ లతా, ప్రాచీన పావైని పాడగల గాజుల సుందరీ, “నన్ను వేంకటేశునికి నియమించు” అని నీవు పలికిన మాటను మేము ఎన్నడూ మీరకుండా అనుగ్రహించు.',
        '1.0': 'మార్గళి మాసపు పౌర్ణమి శుభదినాన స్నానానికి రండి, చక్కని ఆభరణాల అమ్మాయిలారా, సమృద్ధమైన ఆయ్‌ప్పాడి సంపన్న బాలికలారా. వాడి శూలం, తీవ్ర కర్మలు గల నందగోపుని కుమారుడు, అందమైన కన్నుల యశోద లేత సింహం, మేఘవర్ణ దేహుడు, ఎర్రని కన్నులవాడు, సూర్యచంద్రుల వంటి ముఖం గలవాడు, ఆ నారాయణుడే మాకు పఱై ఇస్తాడు. లోకం పొగిడేలా వ్రతంలో చేరండి.',
        '1.1': 'ఈ లోకంలో జీవించేవారలారా, మా వ్రతానికి మేము పాటించే నియమాలు వినండి. పాలకడలిలో మెల్లగా శయనించిన పరమాత్ముని పాదాలను పాడతాం. నెయ్యి తినం, పాలు తాగం; తెల్లవారుజామునే స్నానం చేస్తాం; కళ్ళకు కాటుక పెట్టం, పూలు ముడవం; చేయకూడనివి చేయం, చాడీలు చెప్పం; భిక్షలు దానాలు తోచినంత ఇచ్చి, ఉద్ధరణ మార్గాన్నే ఆలోచిస్తూ ఆనందిస్తాం.',
        '1.2': 'ఎత్తుగా పెరిగి లోకాలను కొలిచిన ఉత్తముని పేరు పాడి, మా వ్రతానికి సమర్పించి స్నానం చేస్తే, ఏ హానీ లేకుండా దేశమంతా నెలకు మూడు వానలు కురుస్తాయి; పొడవైన ఎర్రవరి మధ్య చేపలు దుముకుతాయి; కలువ పూలలో తుమ్మెదలు నిద్రిస్తాయి; ఉదార గోవులు కదలక నిలిచి, నిండిన పొదుగు పట్టగానే కుండలు నింపుతాయి; ఎన్నటికీ తరగని సంపద నిండుతుంది.',
        '1.3': 'సముద్రమంత గంభీరుడవైన వర్షాధిపా, ఏదీ దాచుకోకు. సముద్రంలో ప్రవేశించి నీరు తీసుకొని గర్జిస్తూ పైకి ఎక్కు; ప్రళయకాల ఆదిపురుషుని రూపంలా నల్లబడు; బలమైన భుజాల పద్మనాభుని చేతి చక్రంలా మెరిసి, దక్షిణావర్త శంఖంలా ఉరుము; ఆలస్యం చేయక ఆయన శార్ఙ్గ ధనుస్సు బాణవర్షంలా లోకం బ్రతికేలా కురువు; మేమూ మార్గళిలో ఆనందంగా స్నానం చేస్తాం.',
        '1.4': 'శుద్ధులమై వచ్చి, పవిత్ర పుష్పాలు చల్లి ఆ మాయావిని పూజిద్దాం: పురాతన ఉత్తర మథురా పుత్రుడు, నిర్మల యమునా తీర నివాసి, గోపకులంలో ఉద్భవించిన మంగళదీపం, తల్లి గర్భాన్ని వెలిగించిన దామోదరుడు. నోటితో పాడి మనసుతో ధ్యానిస్తే, గతంలో చేసిన, ఇకపై రాబోయే పాపాలు అగ్నిలో ధూళిలా అవుతాయి. ఆయన నామాన్ని పలకండి.',
        '2.0': 'పక్షులు కూస్తున్నాయి; గరుడాధిపుని ఆలయంలో తెల్లని శంఖ మహానాదం నీకు వినిపించడం లేదా? లేవమ్మా! రాక్షసి స్తన్య విషాన్ని త్రాగి, మోసపు బండిని తన్ని పగులగొట్టిన వానిని, ప్రళయజలంలో శేషునిపై శయనించిన మూలబీజాన్ని హృదయంలో ఉంచుకొని మునులు యోగులు మెల్లగా లేచి “హరి” అనే మహాఘోష మా హృదయంలో ప్రవేశించి చల్లబరుస్తుంది.',
        '2.1': 'భరద్వాజ పక్షులు ఎక్కడ చూసినా “కీచు కీచు” అని కలిసి కూస్తున్న చప్పుడు నీకు వినిపించడం లేదా, వెర్రి అమ్మాయి? సువాసన కురుల గోపికలు చేతులు కదిలించి మెడలోని నాణాల సరాలు గలగలలాడేలా కవ్వంతో పెరుగు చిలుకుతున్న ధ్వని వినిపించడం లేదా? నాయకురాలా! నారాయణ రూపుడు కేశవుని మేము పాడుతున్నా నీవు విని కూడా పడుకునే ఉన్నావా? తేజస్వినీ, తలుపు తెరువు.',
        '2.2': 'తూర్పు ఆకాశం తెల్లబడింది; గేదెలు చిన్న పచ్చిక మేయడానికి చెదిరాయి; బయలుదేరుతున్న మిగతా అమ్మాయిలను ఆపి నిన్ను పిలవడానికి వచ్చి నిలిచాం. ఉత్సాహవతీ, లే; పాడి పఱై పొందుదాం. గుఱ్ఱపు రాక్షసుని నోరు చీల్చి, మల్లురను సంహరించిన దేవాదిదేవుని వెళ్ళి సేవిస్తే, ఆయన “అయ్యో” అని మా అవసరం విచారించి కరుణిస్తాడు.',
        '2.3': 'స్వచ్ఛమైన మణుల మేడలో చుట్టూ దీపాలు వెలుగుతూ, ధూపం పరిమళిస్తూ ఉండగా పరుపుపై నిద్రిస్తున్న మేనమామ కూతురా, మణి తలుపు గడియ తెరువు. అత్తయ్యా, ఆమెను లేపరా? మీ కుమార్తె మూగదా, చెవిటిదా, బద్ధకస్తురాలా? గాఢ నిద్రలో కాపలా వేశారా, మంత్రం వేశారా? “మామాయన్, మాధవ, వైకుంఠ” అని ఆయన పేర్లు అనేకం పలుకుదాం.',
        '2.4': 'వ్రతంతో స్వర్గం చేరబోయే అమ్మాయీ! తలుపు తెరవనివారు ఒక్క మాటైనా జవాబు ఇవ్వరా? సువాసన తులసి ధరించిన నారాయణుడు స్తుతించినవారికి పఱై ఇచ్చే పుణ్యమూర్తి. పూర్వం యమునినోట పడిన కుంభకర్ణుడు తన మహానిద్రను ఓడి నీకే ఇచ్చాడా? ఇంత గాఢ నిద్ర గలదానా, అమూల్య రత్నమా, స్పష్టంగా వచ్చి తలుపు తెరువు.',
        '2.5': 'దూడలతో కూడిన ఎన్నో పశువుల మందలను పితికి, శత్రువుల బలం నశించేలా వెళ్ళి యుద్ధం చేసే నిర్దోష గోపకుల బంగారు లతా, పుట్టలోని పాము వంటి నడుము గల అడవి నెమలీ, బయటకు రా. నీ బంధువులు, చెలులు అందరూ నీ ముంగిట ప్రవేశించి మేఘవర్ణుని నామం పాడుతున్నారు, నీవు కదలవు మాట్లాడవు. సంపన్న కన్యా, ఎందుకు నిద్రిస్తావు?',
        '2.6': 'దూడలపై జాలితో అరిచే లేత గేదెల పొదుగుల నుండి పాలు కారి ఇంటిని బురదగా చేసే సంపన్నుని చెల్లెలా, మంచు మా తలలపై పడుతుండగా నీ గుమ్మం పట్టుకొని, కోపంతో దక్షిణ లంకాధిపతిని సంహరించిన మనసుకు ఇష్టుని పాడుతున్నా నీవు నోరు తెరవవు. ఇప్పటికైనా లే; ఇదేమి గాఢ నిద్ర? ఇంటివారందరికీ తెలిసిపోయింది.',
        '2.7': 'పక్షి రూప రాక్షసుని నోరు చీల్చి, దుష్ట రావణుని చిదిమి పారవేసిన వాని కీర్తి పాడుతూ అమ్మాయిలందరూ వ్రత స్థలానికి వెళ్ళారు. శుక్రుడు ఉదయించాడు, గురుడు నిద్రించాడు; పక్షులు కూస్తున్నాయి. లేడి కన్నుల అమ్మాయీ, చల్లని నీటిలో మునిగి స్నానం చేయకుండా పక్కలోనే పడుకుంటావా? ఈ శుభదినాన కపటం విడిచి మాతో చేరు.',
        '2.8': 'మీ పెరటి తోటలోని కొలనులో ఎర్రకలువలు విచ్చుకున్నాయి, తెల్ల కలువలు ముడుచుకున్నాయి. కాషాయవస్త్రాల, తెల్లని పళ్ళ తపస్వులు తమ ఆలయంలో శంఖం ఊదడానికి వస్తున్నారు. మమ్మల్ని ముందుగా లేపుతానని గప్పాలు కొట్టిన నీకు సిగ్గు లేదా? మాటల చతురురాలా, లే; శంఖచక్రాలు ధరించిన పెద్ద చేతుల కమలనేత్రుని పాడు.',
        '2.9': '“ఓ చిన్న చిలుకా, ఇంకా నిద్రపోతున్నావా?” “అమ్మాయిలూ, అలా వాడిగా పిలవకండి; వస్తున్నాను.” “నీ మాటల నేర్పు మాకు ముందే తెలుసు.” “నేర్పరులు మీరే; సరే నేనే అనుకోండి.” “త్వరగా రా; నీకేమి ప్రత్యేకత?” “అందరూ వచ్చారా?” “వచ్చారు; వచ్చి లెక్కపెట్టుకో.” బలమైన ఏనుగును చంపినవాడు, శత్రువులను నాశనం చేయగల మాయావి గురించి పాడుదాం.',
        '3.0': 'మా నాయకుడు నందగోపుని మందిర రక్షకుడా, ధ్వజతోరణాల ద్వార పాలకుడా, మణి తలుపు గడియ తెరువు. మేము గొల్ల బాలికలం; ఇంద్రనీలవర్ణ మాయావి నిన్ననే మాకు మోగే పఱై ఇస్తానని మాట ఇచ్చాడు. శుద్ధంగా వచ్చాం, ఆయనను పాడి లేపడానికి. ముందే నోటితో వద్దనకు; ప్రేమతో గడియ తీసి తలుపు తెరువు.',
        '3.1': 'వస్త్రం, నీరు, అన్నం దానం చేసే మా ప్రభువు నందగోపాలా, లెమ్ము. సుందరీమణులందరిలో చిగురువైన, కులదీపమైన మా ప్రభ్వి యశోదా, మేల్కొను. ఆకాశాన్ని చీల్చి ఎదిగి లోకాలను కొలిచిన దేవాధిపా, నిద్రించక లెమ్ము. బంగారు అందెల సిరివంతుడు బలదేవా, నీవు నీ తమ్ముడు ఇక నిద్రించకండి.',
        '3.2': 'మదగజంలా వెనుతిరగని భుజబలం గల నందగోపాలుని కోడలా నప్పిన్నైవా, సుగంధ కురులదానా, తలుపు తెరువు. అంతటా కోళ్ళు కూశాయి; మాధవీ పందిరిపై కోకిలలు పదేపదే కూస్తున్నాయి. బంతి పట్టిన వేళ్ళ దానా, నీ మేనబావ పేరు పాడడానికి, ఎర్రతామర చేతితో గాజులు మోగేలా వచ్చి తలుపు తెరువు, ఆనందంగా.',
        '3.3': 'కుందెల దీపం వెలుగుతుండగా, ఏనుగు దంతపు కాళ్ళ మంచంపై మెత్తని పంచశయనంపై ఎక్కి, పూగుత్తుల కురుల నప్పిన్నై వక్షంపై శయనించిన పుష్ప వక్షా, మాట్లాడు. కాటుక పెట్టిన విశాల నేత్రాల దానా, నీ భర్తను ఏ ఒక్క క్షణమూ లేవనివ్వవు, క్షణమైనా విడిచి ఉండలేవు. అది ధర్మం కాదు, దయ కూడా కాదు.',
        '3.4': 'ముప్ఫై మూడు కోట్ల దేవతల ముందు వెళ్ళి వారి వణుకును తీర్చే శూరుడా, లెమ్ము. నిజాయితీ గలవాడా, పరాక్రమశాలీ, శత్రువులకు తాపం ఇచ్చే నిర్మలా, లెమ్ము. భరిణెలాంటి మెత్తని వక్షోజాలు, ఎర్రని పెదవులు, సన్నని నడుము గల నప్పిన్నా, లక్ష్మీ, లెమ్ము. విసనకర్ర, అద్దం ఇచ్చి నీ భర్త చేత ఇప్పుడే మాకు స్నానం చేయించు.',
        '3.5': 'పాత్రలు పొంగి పొరలేలా ఆపకుండా పాలు కురిపించే ఉదార గోవుల సంపద గలవాని కుమారుడా, మేల్కొను. స్థిరమైనవాడా, మహనీయుడా, లోకంలో ఉద్భవించిన జ్యోతీ, లెమ్ము. బలం కోల్పోయిన శత్రువులు నీ గుమ్మానికి వచ్చి నీ పాదాలపై పడినట్లు, మేము స్తుతిస్తూ వచ్చాం.',
        '3.6': 'ఈ విశాల భూమిపై రాజులు గర్వభంగమై వచ్చి నీ పాన్పు కింద గుంపుగా కూర్చున్నట్లు మేమూ వచ్చి చేరాం. గజ్జె నోరు వంటి విచ్చిన తామరలాంటి నీ ఎర్రని కన్నులు మామీద కొంచెమైనా తెరవవా? చంద్రసూర్యులు కలిసి ఉదయించినట్లు ఆ రెండు కన్నులతో మమ్మల్ని చూస్తే మా శాపం తొలగిపోతుంది.',
        '4.0': 'వర్షాకాలంలో గుహలో నిద్రించిన శ్రేష్ఠ సింహం మేల్కొని, నిప్పులాంటి కన్నులు తెరిచి, సువాసన జూలు నిక్కబొడిచి అన్ని వైపులా విదిలించి, ఒళ్ళు విరుచుకొని గర్జిస్తూ బయటకు వచ్చినట్లు, కాయాంబూ పువ్వు వర్ణం గలవాడా, నీవు నీ మందిరం నుండి ఇక్కడికి వచ్చి, శ్రేష్ఠ సింహాసనంపై కూర్చొని మేము వచ్చిన పనిని విచారించి అనుగ్రహించు.',
        '4.1': 'ఆనాడు ఈ లోకాన్ని కొలిచిన నీ పాదానికి జయం; అక్కడికి వెళ్ళి దక్షిణ లంకను నాశనం చేసిన నీ పరాక్రమానికి జయం; బండిని తన్ని చంపిన నీ కీర్తికి జయం; దూడ రూప రాక్షసుని విసిరే కర్రగా చేసిన నీ అందెకు జయం; గోవర్ధన పర్వతాన్ని గొడుగుగా ఎత్తిన నీ గుణానికి జయం; గెలిచి శత్రువులను నాశనం చేసే నీ చేతి శూలానికి జయం. ఇలా నీ పరాక్రమాన్ని స్తుతిస్తూ పఱై పొందడానికి ఈ రోజు వచ్చాం; కరుణించు.',
        '4.2': 'ఒక స్త్రీకి కొడుకై పుట్టి అదే రాత్రి మరొక స్త్రీకి కొడుకై దాగి పెరిగినవాడా, సహించక కీడు తలచిన కంసుని ఉద్దేశ్యాన్ని భగ్నం చేసి అతని కడుపులో నిప్పులా నిలిచిన నెడుమాలా, నిన్ను యాచించి వచ్చాం. పఱై ఇస్తే నీ శ్రేష్ఠ సంపదను, శౌర్యాన్ని పాడి దుఃఖం పోగొట్టుకొని ఆనందిస్తాం.',
        '4.3': 'ఇంద్రనీలవర్ణా! మార్గళి స్నానానికి పెద్దలు చేసే నియమంలో కావలసినవి అడిగితే చెబుతాం: లోకమంతా వణికేలా మ్రోగే, పాలవంటి తెల్లని నీ పాంచజన్యంలాంటి శంఖాలు, పెద్ద పఱై వాద్యం, “పల్లాండు” పాడేవారు, అందమైన దీపం, ధ్వజం, చాందినీ. మర్రి ఆకుపై శయనించినవాడా, అనుగ్రహించు.',
        '4.4': 'కలవనివారినీ గెలిచే కీర్తిగల గోవిందా, నిన్ను పాడి పఱై తీసుకొని మేము పొందే బహుమానాన్ని దేశమంతా పొగుడుతుంది. కంకణాలు, భుజకీర్తులు, చెవి పోగులు, చెవి పూలు, అందెలు మొదలైన ఎన్నో ఆభరణాలు ధరిస్తాం; కొత్త బట్టలు కడతాం. ఆ తరువాత కలిసి కూర్చొని నెయ్యి కప్పి మోచేతి వరకు కారే పాలన్నం తిని ఆనందంతో చల్లబడతాం.',
        '4.5': 'ఆవుల వెనుక వెళ్ళి అడవిలో చేరి అక్కడే తింటాం. ఏమీ తెలియని గోపకులంలో నీవు పుట్టిన పుణ్యం మాకుంది. ఏ లోటూ లేని గోవిందా, నీతో మా బంధం తెంచినా తెగదు. ఏమీ తెలియని బాలికలమైన మేము ప్రేమతో నిన్ను చిన్న పేర్లతో పిలిచినా కోపగించకు; ప్రభూ, పఱై ఇవ్వు.',
        '4.6': 'తెల్లవారుజామునే వచ్చి నిన్ను సేవించి నీ బంగారు తామర పాదాలను స్తుతించే కారణం వినుము. పశువులు మేపి బ్రతికే కులంలో పుట్టిన నీవు మా సేవను స్వీకరించకుండా వెళ్ళరాదు. గోవిందా, మేము వచ్చింది నేటి పఱై కోసమే కాదు. ఎల్లప్పుడూ, ఏడేడు జన్మలకూ నీవారమే, నీకే సేవ చేస్తాం. మా ఇతర కోరికలను మార్చు.',
        '4.7': 'ఓడలున్న సముద్రాన్ని మథించిన మాధవుని, కేశవుని చంద్రముఖులైన ఆభరణాల కన్యలు వెళ్ళి నమస్కరించి పఱై పొందిన విధాన్ని, అందమైన పుదువై నగరపు చల్లని పచ్చని తామరమాల ధరించిన భట్టర్‌పిరాన్ కూతురు కోదై చెప్పిన సంగ కాల తమిళ మాలిక ముప్పై పద్యాలు తప్పక పఠించేవారు, నాలుగు పర్వతాల వంటి భుజాలు, ఎర్రని కన్నులు, సుందర ముఖం గల శ్రీమంతుడైన తిరుమాల్ కృపను ఎల్లెడలా పొంది సుఖిస్తారు.',
        '5.0': 'ఆడి మాసపు పూరం నక్షత్రంలో జగత్తులో అవతరించినది చిరంజీవి అగుగాక; తిరుప్పావై ముప్పై పాశురాలు చెప్పినది చిరంజీవి అగుగాక; పెరియాళ్వార్ పెంచిన కుమార్తె చిరంజీవి అగుగాక; పెరుంబూదూరు మహాముని (రామానుజుల) తరువాత వచ్చినది చిరంజీవి అగుగాక; నూట నలభై మూడు పద్యాలు చెప్పినది చిరంజీవి అగుగాక; ఉన్నత రంగనాథునికి ఆనందంగా తన మాలను ఇచ్చినది చిరంజీవి అగుగాక; సువాసన తిరుమల్లి నాడు స్వామిని చిరంజీవి అగుగాక; ఉదార పుదువై నగర కోదై పుష్ప పాదాలు చిరంజీవులగుగాక.',
      },
    },
    'skanda-shashti-kavacham': {
      summary: 'బాల దేవరాయ స్వామిగళ్ తమిళంలో రచించిన మురుగన్ “కవచం”. ప్రభువును వేలు, నెమలితో రమ్మని పిలవడం, శిరస్సు, అవయవాలు, దినంలోని ప్రతి సమయాన్ని వేలు రక్షణలో ఉంచమని కోరడం, దుష్ట ప్రభావాలు, జంతువులు, రోగాలను తరిమివేయడం, పఠన ఫలం చెప్పడం ఇందులో ఉన్నాయి. స్కంద షష్ఠి ఆరు రోజుల్లో విశేషంగా పఠిస్తారు.',
      verses: {
        '0.0': 'దీనిని స్తుతించేవారి దుష్కర్మలు పోతాయి, దుఃఖం పోతుంది; హృదయంలో నిలుపుకొనేవారికి సంపద ఫలించి వృద్ధి చెందుతుంది; ధ్యాన నిష్ఠ సిద్ధిస్తుంది. ఇది నిర్మలుని కృపతో కంద షష్ఠి కవచం.',
        '0.1': 'ఓ మనసా, దేవతల కష్టాలు తీర్చడానికి యుద్ధం చేసిన కుమారుని పాదాలను ధ్యానించు.',
        '1.0': 'షష్ఠిని ఉద్దేశించి, శరవణంలో జన్మించిన, సజ్జనులకు సహాయపడే, ఎర్రని కిరణాల వేలాయుధం ధరించిన, రెండు పాదాల్లో అనేక మణుల గజ్జెలు మోగుతూ అందెలు ఆడుతూ మనసు హరించే నృత్యం చేసే మయూరవాహనుని స్మరిస్తున్నాను.',
        '1.1': '“చేతి వేలుతో నన్ను కాపాడు” అని కోరుతూ పిలుస్తున్నాను: “రా రా, వేలాయుధా రా; రా రా, మయూరవాహనా రా; ఇంద్రాది అష్టదిక్పాలకులు కొనియాడే మంత్రస్వరూప వేలా, రా రా.”',
        '1.2': 'ఇంద్రుని అల్లుడా రా రా; ప్రియమైన కురవ కన్య మనసులో నివసించేవాడా రా; ఆరు ముఖాల ప్రభూ రా; నిత్యం విభూతి ధరించే వేలుడా రా; శిరగిరి (చెన్నిమలై) వేలా, త్వరగా రా.',
        '1.3': 'శరవణభవా, త్వరగా రా; తరువాత “రహణ భవచ రరరర రరర”, “రిహణ భవచ రిరిరిరి రిరిరి”, “విణభవ సరహణ వీరా నమో నమ”, “నిభవ సరహణ నిర నిర నిరెన” అనే బీజ ధ్వనులతో షడక్షర ప్రభువును పిలుస్తారు.',
        '1.4': 'రా రా, అసుర కులాన్ని నాశనం చేసిన ప్రభూ; నన్ను పాలించే యువ ప్రభుని చేతుల్లో పన్నెండు ఆయుధాలు, పాశం, అంకుశం, పన్నెండు విశాల నేత్రాలు ప్రకాశిస్తుండగా త్వరగా వచ్చి నన్ను కాపాడు వేలా.',
        '1.5': '“ఐం క్లీం సౌః” బీజాక్షరాలు క్రమంగా వెలిగి, షణ్ముఖుని అనన్య తేజస్సుతో సమమైన కాంతిగా నా ముందు నిలిచి నిత్యం ప్రకాశించుగాక. కుండలినీ నాథా శివగుహా, ప్రతిరోజూ రా.',
        '2.0': 'ఆరు ముఖాలు, ఆరు కిరీటాలు, విభూతి పూసిన నుదురు, పొడవైన కనుబొమలు, పన్నెండు కన్నులు, పగడం వంటి ఎర్ర పెదవులు, నుదుట నవరత్న చుట్టి, పన్నెండు చెవుల్లో కుండలాలు, పన్నెండు బలమైన భుజాలు, అందమైన వక్షం, అనేక ఆభరణాలు పతకాలు, నవరత్న మాలలతో రా.',
        '2.1': 'యజ్ఞోపవీతం, ముత్యాల వక్షం, అందమైన ఉదరం నాభి, వంగే నడుముపై మెరిసే పట్టు వస్త్రం, నవరత్న ఖచిత చక్కని ఖడ్గం, అందమైన తొడలు, జంట మోకాళ్ళతో రా.',
        '2.2': 'పవిత్ర పాదాల్లో అందెలు మోగుతుండగా “సెకగణ సెకగణ సెకగణ సెగణ”, “మొకమొక మొకమొక మొకమొక మొకెన”, “నకనక నకనక నకనక నకెన”, “డికుకుణ డికుడికు డికుకుణ డికుణ” అనే ధ్వనులతో.',
        '2.3': '“రరరర రరరర రరరర రరర”, “రిరిరిరి రిరిరిరి రిరిరిరి రిరిరి”, “డుడుడుడు డుడుడుడు డుడుడుడు డుడుడు”, “డకుడకు డికుడికు డంగు డింగుకు” అనే ధ్వనులతో.',
        '2.4': 'రా రా మయూరాధిపా; ముందుకు రా రా మురుగవేళా; నన్ను పాలించే ఏరకం (స్వామిమలై) అధిపా, నేను కోరిన వరాన్ని సంతోషంగా ఇచ్చే కుమారా.',
        '3.0': '“లాలా లాలా లాలా”, “లీలా లీలా లీలా” అనే ధ్వనులతో, లీలావినోదా: నీ పవిత్ర పాదాలను స్థిర ఆశ్రయంగా నమ్మి వాటిపై ఉంచిన నా శిరస్సును వేలు కాపాడుగాక; నా ప్రాణానికి ప్రాణమైన ప్రభువు కాపాడుగాక; పన్నెండు కన్నుల బాలుడు నన్ను కాపాడుగాక; నా ముఖాన్ని అందమైన వేలు కాపాడుగాక.',
        '3.1': 'విభూతి పూసిన నుదురును పవిత్ర వేలు కాపాడుగాక; మెరిసే రెండు వేలులు నా కన్నులను కాపాడుగాక; వేలవుని వేలు రెండు చెవులను కాపాడుగాక; మంచి వేలు రెండు ముక్కు రంధ్రాలను కాపాడుగాక; గొప్ప వేలు మాట్లాడే నోటిని కాపాడుగాక.',
        '3.2': 'ముప్పై రెండు పళ్ళను వాడి వేలు కాపాడుగాక; నాలుకను ఎర్రని వేలు కాపాడుగాక; రెండు చెంపలను తేజోవేలు కాపాడుగాక; నా లేత కంఠాన్ని మధుర వేలు కాపాడుగాక; వక్షాన్ని రత్నఖచిత వేలు కాపాడుగాక.',
        '3.3': 'వక్షస్థలాన్ని పవిత్ర వేలు కాపాడుగాక; వాడి వేలు రెండు భుజాలను వృద్ధిగా కాపాడుగాక; మెడ వెనుక భాగాలను గొప్ప వేలు కాపాడుగాక; వీపును అందంగా కరుణా వేలు కాపాడుగాక; పదహారు పక్కటెముకలను బలమైన వేలు కాపాడుగాక.',
        '3.4': 'విజయ వేలు ఉదరాన్ని చక్కగా కాపాడుగాక; ఎర్ర వేలు సన్నని నడుమును అందంగా కాపాడుగాక; మంచి వేలు నడుము దారాన్ని కాపాడుగాక; వాడి వేలు గుహ్యాంగాన్ని కాపాడుగాక; గొప్ప వేలు రెండు తుంటులను కాపాడుగాక.',
        '3.5': 'గుదాన్ని బలమైన వేలు కాపాడుగాక; రెండు తొడలను లావైన వేలు కాపాడుగాక; పిక్కలు మోకాళ్ళను తేజోవేలు కాపాడుగాక; ఐదు వేళ్ళ పాదాలను అనుగ్రహ వేలు కాపాడుగాక; రెండు చేతులను కరుణా వేలు కాపాడుగాక.',
        '3.6': 'రెండు ముంజేతులను బలమైన వేలు కాపాడుగాక; వెనుక చేతులతో చిన్న రాణి వల్లి ఉండుగాక; నాలుకపై సరస్వతి మంచి తోడు అగుగాక; నాభి కమలాన్ని మంచి వేలు కాపాడుగాక; మూడు నాడులను వాడి వేలు కాపాడుగాక.',
        '3.7': 'ఎదురు వేలు ఎల్లప్పుడూ నన్ను కాపాడుగాక. నా మాట, కదలిక సమయంలో బంగారు వేలు త్వరగా వచ్చి కాపాడుగాక. రాబోయే పగటిలో వజ్ర వేలు కాపాడుగాక; అర్ధ చీకటిలో మంచి వేలు కాపాడుగాక; అర్ధరాత్రి, యామాల్లో ఎదురు వేలు కాపాడుగాక; అన్ని ఆలస్యాలను తొలగించి నేర్పరి వేలు కాపాడుగాక.',
        '3.8': 'కాపాడు కాపాడు కనక వేలా; చూడు చూడు క్షణంలో చూడు; కొట్టు కొట్టు అడ్డు లేకుండా కొట్టు; చూడు చూడు పాపం పొడిపొడి అయ్యేలా; చేతబడి, క్షుద్రం, పెద్ద వైరం తొలగిపోవుగాక.',
        '4.0': 'బలమైన భూతాలు, వలాష్టిక ప్రేతాలు, బాధించే అదుపు లేని ముని ప్రేతం, పిల్లలను తినే పెరటి ముని, కొరివి నోటి పిశాచాలు, చాడీ పిశాచాలు, స్త్రీలను వెంబడించే బ్రహ్మరాక్షసులు: ఇవన్నీ',
        '4.1': 'ఈ సేవకుని చూసి వణకి కలవరపడుగాక: ఇరిసి కాట్టేరి వంటి ఈ బాధల సేన, పగలు రాత్రి ఎదురయ్యే అణ్ణరులు, పెద్ద పూజలు తీసుకునే కాళితో వచ్చే వారందరూ, విట్టాంగారులు, అనేక ప్రేతాలు, తండియకారులు, చండాలులు.',
        '4.2': 'నా పేరు చెప్పగానే పిడుగు పడి పారిపోవుగాక; ఏనుగు అడుగులో పాతిన కీడు బొమ్మలు, పిల్లి వెంట్రుకలు, పిల్లల ఎముకలు, గోళ్ళు, వెంట్రుకలు, పొడవైన జుట్టుతో కపాలం.',
        '4.3': 'బొమ్మలతో కలశాలు, ఇంట్లో పాతిన మోసపు వస్తువులు, పట్టినవారి గర్వం, దాని కోసం చేసిన బొమ్మ, కాసులు, డబ్బు, గుడిలో ఉంచిన అన్నం, మంత్రించిన కాటుక, ఒకే దారి చేతబడి:',
        '4.4': 'నన్ను చూసి వీరందరూ తిరుగాడి చెదరిపోవుగాక; శత్రువులు, మోసగాళ్ళు వచ్చి నాకు నమస్కరించుదురుగాక; యమదూతలు నన్ను చూసి వణకుదురుగాక; భయపడి దొర్లుదురుగాక; నోరు తెరిచి అరచి బుద్ధి కోల్పోయి పరిగెత్తుదురుగాక.',
        '4.5': 'నేలపై కొట్టుకునేలా పాశపు తాడుతో కట్టు; శరీరం అరచేలా కట్టు; కాళ్ళు చేతులు విరిగేలా కట్టి దొర్లించు; కట్టు కట్టు ఏడ్చేలా కట్టు; కొట్టు కొట్టు కళ్ళు ఉబ్బేలా.',
        '4.6': 'నలుపు నలుపు ముక్కలు ముక్కలుగా; సూరుని శత్రువును కొట్టు కొట్టు; వాడి వేలుతో పొడువు పొడువు; సూర్యుని నిప్పు తాపంతో పట్టు పట్టు; మంటలు మంటలు మంటలు అవుగాక; వేలు వదులు వదులు, వారు భయపడి పరుగెత్తుదురుగాక.',
        '4.7': 'పులి, నక్క, అడవి పంది, కుక్కలు, ఎలుకలు, ఎలుగుబంట్లు నన్ను వెంబడించక పారిపోవుగాక; తేలు, పాము, విషపు జెర్రి, వాటి కాటు విషం శరీరంలోకి ఎక్కినా సులభంగా దిగుగాక.',
        '4.8': 'వాపు, బెణుకు, తలనొప్పి, వాతం, ఫిట్స్, పిత్తం, శూల, క్షయ, గుల్మం, దురద, కురుపులు, పొట్ట సమస్యలు మొదలైన రోగాలు పోవుగాక; ప్రక్క వాపు, తొడ వాపు, అరటి వంటి వాపు కూడా పోవుగాక.',
        '4.9': 'కురుపులు, పుండ్లు, పంటినొప్పి మొదలైన అన్ని రోగాలు నన్ను చూసి నిలువక పారిపోవుగాక; ప్రభూ, పద్నాలుగు లోకాలూ నాకు బంధువులు కావాలని, స్త్రీ పురుషులందరూ నావారు కావాలని, నేలనేలే రాజులు సంతోషంగా నాకు ఆప్తులు కావాలని అనుగ్రహించు.',
        '5.0': 'నిన్ను స్తుతించడానికి నీ పవిత్ర నామాలు: శరవణభవ, శైలొళిభవ, త్రిపురభవ, తిగళొళిభవ, పరిపురభవ, భవాన్ని నశింపజేసేవాడా, హరి లక్ష్ముల మేనల్లుడా, అమరావతి కఠిన కారాగారం నుండి దేవతలను విడిపించి కాపాడినవాడా.',
        '5.1': 'కందా, గుహా, మెరిసే వేలవా, కార్తికేయ కుమారా, కదంబా, కదంబనై, ఇడుంబుని సంహరించిన మధుర వేల మురుగా, తణికాచల నాథా, శంకర పుత్రా, కతిర్కామ వేల మురుగా, పళని బాలకుమారా, ఆవినన్కుడి అందమైన వేలా, తిరుచెందూరు సెంగల్వరాయా, సమరాపురి షణ్ముఖ రాజా.',
        '5.2': 'నల్లని కురుల సరస్వతి మంచి తోడు అగుగాక; నా నాలుకపై ఆమె ఉన్నందున నిన్ను పాడతాను; నన్ను వెంబడించే తండ్రి మురుగుని పాడాను, పరవశంతో నాట్యం చేశాను; నాట్యం చేసి ఆవినన్కుడి విభూతిని కోరాను.',
        '5.3': 'దానిని ప్రేమతో నుదుట ధరించడానికి కర్మ బంధాలు వదులవుగాక; నీ కృపతో నీ పాదాలు చేరడానికి ప్రేమతో కాపాడు; మాటిమాటికీ వేలాయుధుడు అన్నం, బంగారం ఇచ్చుగాక; సిద్ధి పొంది ఈ సేవకుడు సుఖంగా జీవించుగాక.',
        '6.0': 'మయూరాధిపునికి జయం; వాడి వేలుకు జయం; కొండల గురువుకు జయం; కొండ కురవ కన్య వల్లితో ఆయనకు జయం; కోడి ధ్వజానికి జయం; నా పేదరికం తొలగేలా జయం.',
        '6.1': 'ఎన్ని లోపాలు, ఎన్ని తప్పులు, ఈ సేవకుడు ఎన్ని చేసినా, నీవే తండ్రివి గురువువు, క్షమించడం నీ కర్తవ్యం; కొండ కురవ కన్య నన్ను కన్న తల్లి. కుమారుడని ప్రేమ ఇచ్చి, సంతోషించి, భక్తులు వర్ధిల్లేలా అనుగ్రహించు; నీవు కోరిన ఈ కంద షష్ఠి కవచాన్ని స్వీకరించు.',
        '6.2': 'బాల దేవరాయలు చెప్పిన దీనిని ఉదయం సాయంత్రం భక్తితో నిత్యం, శుచిగా దేహం కడుక్కొని, ప్రేమతో ఒకే ఆలోచనతో, చింత లేని మనసుతో ఈ కంద షష్ఠి కవచాన్ని ధ్యానించేవారికి ఈ ఫలాలు కలుగుతాయి.',
        '7.0': 'ఒక రోజు ముప్పై ఆరు సార్లు పఠించి ఆనందంగా విభూతి ధరిస్తే, అష్టదిక్కుల వారందరూ వశులవుతారు; దిక్పాలకులు అనుగ్రహిస్తారు; శత్రువులందరూ వచ్చి నమస్కరిస్తారు.',
        '7.1': 'నవగ్రహాలు సంతోషించి మేలు చేస్తాయి; నవ మన్మథుని వంటి అందం పొందుతారు; ఎల్లప్పుడూ పదహారేళ్ళ ప్రాయంలా జీవిస్తారు; కంద కైవేలే ఈ కవచం; మార్గంలో చూసినవారికి అది ఆధారంగా ప్రకాశిస్తుంది, కంటితో చూస్తే ప్రేతాలు భయపడి పరుగెత్తుతాయి.',
        '7.2': 'కంటితో చూస్తే భూతాలు భయపడి పారిపోతాయి; దుష్టులను పొడిపొడి చేస్తుంది; సజ్జనుల మనసులో నాట్యం చేస్తుంది; సర్వ శత్రు సంహారక పాదం అది.',
        '8.0': 'ఎనిమిది లక్ష్ములలో ఉన్న నా మనస్సును తెలిసి, సూరపద్ముని ఖండించిన చేతితో వీరలక్ష్మికి, ఇరవై ఏడు మందికి అమృతం విందుగా ఇచ్చిన, పళని కొండపై ఉండే గురుపరుని చిన్న బిడ్డకు నమస్కారం.',
        '8.1': 'ఆ బాలుని ఎర్రని పాదాలకు నమస్కారం; నన్ను ఆపి ఏలుకొని నా మనసులో చేరిన ప్రభువుకు నమస్కారం; తగిన రూపం గల వేలవునికి నమస్కారం; దేవతల సేనాపతికి నమస్కారం; కురవ కన్య మనసు ఆనందింపజేసిన ప్రభువుకు నమస్కారం; గొప్ప సామర్థ్యం గల దివ్య దేహునికి నమస్కారం.',
        '8.2': 'ఇడుంబాయుధా, ఇడుంబ సంహారకా నమస్కారం; కదంబా నమస్కారం, కందా నమస్కారం; వెట్చి పువ్వు ధరించే ప్రభూ నమస్కారం; ఉన్నత గిరి, కనక సభకు ఏకైక రాజా; నెమలిని ఆడించేవాడా, నీ పాదాలకు శరణం. శరణం శరణం శరవణభవ ఓం; శరణం శరణం షణ్ముఖా శరణం.',
      },
    },
    'anjaneya-dandakam': {
      summary: 'హనుమంతుని స్తుతిస్తూ తెలుగులో సాగే ఒక పొడవైన, విరామం లేని దండకం. ప్రారంభ నమస్కారాల తరువాత సుగ్రీవునికి, శ్రీరామునికి హనుమంతుడు చేసిన సేవలను స్మరిస్తుంది: సీతను చూడడం, లంకను కాల్చడం, సంజీవినిని తేవడం, అయోధ్యలో పట్టాభిషేకం. భూతప్రేతాల భయం నుండి రక్షణ కోసం ప్రార్థనతో, మాటిమాటికీ నమస్కారాలతో ముగుస్తుంది. మంగళ, శనివారాల్లో దీనిని విశేషంగా పఠిస్తారు.',
      verses: {
        '0.0': 'ప్రసన్నుడైన ఆంజనేయుని, కాంతివంతమైన దివ్య శరీరుని, కీర్తినిచ్చేవానిని భజిస్తున్నాను; వాయుపుత్రుని, తోక గల శరీరునిని భజిస్తున్నాను; పవిత్రుని భజిస్తున్నాను; సూర్యమిత్రుని, రుద్రరూపుని, బ్రహ్మతేజస్వినిని భజిస్తున్నాను, అని.',
        '0.1': 'ఉదయం సాయంత్రం నీ నామ సంకీర్తన చేసి, నీ రూపాన్ని వర్ణించి, నీపై ఈ ఒక్క దండకం చేయడానికి, నీ మూర్తిని ఊహించి నీ సౌందర్యాన్ని తలచి, నీ దాసదాసుడనై, రామభక్తుడనై నిన్ను కొలుస్తున్నాను.',
        '0.2': 'నీ కటాక్షంతో నన్ను చూస్తే, సంతోషిస్తే, నా మొర ఆలకిస్తే, నన్ను రక్షిస్తే, అంజనాదేవి గర్భంలో జన్మించిన దేవా, నిన్ను తలచడానికి నేనెంతవాడిని?',
        '1.0': 'దయతో చూసి, దాతవై కాపాడి, దగ్గర నిలిచావు. పూర్వం సుగ్రీవునికి మంత్రివై స్వామి కార్యానికి వెళ్ళి, రామలక్ష్మణులను చూసి విచారించి, సర్వేశ్వరుని పూజించి, సూర్యపుత్రుడైన సుగ్రీవుని ఆయనకు సేవకునిగా చేశావు.',
        '1.1': 'వాలిని సంహరింపజేసి, కాకుత్స్థ తిలకుడైన శ్రీరాముడు కృపాదృష్టితో చూశాడు. కిష్కింధకు వచ్చి శ్రీరామ కార్యానికి లంకకు వెళ్ళి, లంకిణిని చంపి లంకను కాల్చావు.',
        '1.2': 'భూమిజ సీతను చూసి ఆనందం ఉప్పొంగి ఆమెకు ఉంగరం ఇచ్చి, ఆ రత్నాన్ని తెచ్చి శ్రీరామునికిచ్చి సంతోషపరచావు. సుగ్రీవుడు, అంగదుడు, జాంబవంతుడు, నలుడు, నీలులతో కలిసి ఆ సేతువును దాటి, వానరులు పెద్ద సేనలై దైత్యులను సంహరించారు.',
        '1.3': 'అప్పుడు రావణుడు కాలాగ్నిరుద్రునిలా వచ్చి బ్రహ్మాండమైన ఆ శక్తిని విసిరి లక్ష్మణుని మూర్ఛపోయేలా చేయగా, అప్పుడే నీవు సంజీవినిని తెచ్చి సౌమిత్రికిచ్చి ప్రాణాలు రక్షించావు.',
        '1.4': 'కుంభకర్ణాది వీరులతో పోరాడగా శ్రీరామ బాణాగ్ని వారందరినీ, రావణుని సంహరించగా, లోకాలు ఆనందమయమై ఉండగా, ఆ సమయంలో విభీషణుని వేడుకగా తోడ్కొని వచ్చి పట్టాభిషేకం చేయించావు.',
        '1.5': 'సీతా మహాదేవిని తెచ్చి శ్రీరామునికి అప్పగించావు. అనంతరం అయోధ్యను ప్రవేశించి పట్టాభిషేక సంరంభం జరుగుతుండగా, “నీకంటే నాకు ప్రియులు ఎవరూ లేరు” అని ఆయన నిన్ను సన్మానించాడు.',
        '2.0': 'శ్రీరామభక్తి ప్రశస్తంగా నిన్ను సేవించి నీ కీర్తనలు చేస్తే, పాపాలు పోతాయా, భయాలు తీరతాయా, భాగ్యాలు కలుగుతాయా, సామ్రాజ్యాలు, సంపదలు కలుగుతాయా?',
        '2.1': 'వానరాకారా, భక్త మందారా, పుణ్య సంచారీ, ధీరా, వీరా; నీవే సమస్తమని తలచి, తారక బ్రహ్మ మంత్రాన్ని స్థిరంగా పఠిస్తూ, వజ్రదేహం ధరించి, “శ్రీరామ శ్రీరామ” అంటూ పవిత్ర మనసుతో ఎప్పుడూ తప్పకుండా స్మరిస్తాను. నా నాలుకపై ఉండి, ముల్లోకాల సంచారి అయిన నీ దీర్ఘ దేహంతో, రామనామ ధ్యానంతో, బ్రహ్మతేజస్సుతో, రౌద్ర జ్వాలా కల్లోలంతో, వీర హనుమంతా:',
        '2.2': 'ఓంకార శబ్దంతో భూతప్రేతాలను, గొప్ప పిశాచాలను, శాకినీ డాకినీ మొదలైనవారిని, గాలి దయ్యాలను నీ తోకతో చుట్టి, నేలపై కొట్టి, పిడికిలి దెబ్బలతో, బాహుదండాలతో, రోమ ఖండాలతో విరిచి, కాలాగ్ని రుద్రుడవై, బ్రహ్మప్రభతో ప్రకాశించే నీ దివ్య తేజస్సును చూసి “రారా నా ముద్దు నరసింహా” అంటూ దయాదృష్టితో చూసి నన్ను ఏలుకో, నా స్వామీ ఆంజనేయా.',
        '3.0': 'సదా బ్రహ్మచారివైన నీకు నమస్కారం; వాయుపుత్రునికి నమో నమః; నీకు నమస్కారం.',
      },
    },
    'annamacharya-brahma-kadigina-padamu': {
      summary: 'బ్రహ్మ కడిగిన, భూమిని ఆకాశాన్ని కొలిచిన, బలిని అణచిన, అహల్య పాపాన్ని కడిగిన, కాళియుని పడగపై నర్తించిన, లక్ష్మి ఒత్తే, వేంకటగిరి చూపిన పరమపదమైన స్వామి పాదాలను అన్నమయ్య స్తుతిస్తారు. ముఖారి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'బ్రహ్మ కడిగిన పాదం; తానే పరబ్రహ్మమైన పాదం.',
        '1.0': 'ఆనందంగా భూమిని కొలిచిన నీ పాదం, బలి తలపై ఉంచిన పాదం, ఆకాశాన్ని తన్నిన పాదం, ఇంద్రుని కాపాడిన పాదం.',
        '1.1': 'ఆ స్త్రీ (అహల్య) పాపాన్ని కడిగిన పాదం, పాము తలపై ఉంచిన పాదం, శ్రీదేవి ప్రేమతో ఒత్తే పాదం, గుర్రపు రూపం (కల్కి) పాదం.',
        '1.2': 'శ్రేష్ఠ యోగులకు అనేక విధాల పరమ ఫలాన్ని ఇచ్చే నీ పాదం; తిరువేంకటగిరి స్థిర ఆశ్రయమని చూపిన పరమపదం నీ పాదం.',
      },
    },
    'annamacharya-cheri-yasodaku': {
      summary: 'యశోద వద్దనున్న ఈ శిశువే బ్రహ్మకు తండ్రి, జగదీశుడు; ఆయన చూపుతో సూర్యచంద్రులు ప్రకాశిస్తారు, ఆయన ఊపిరి వేదాలు, సముద్రం. చివరకు ఆయన శరణాగతుల ఆశ్రయమైన శ్రీ వేంకటేశుడని తెలుస్తుంది. మోహన రాగంలో పాడతారు.',
      verses: {
        '0.0': 'యశోద చెంతకు చేరిన ఈ శిశువే భూమిపై బ్రహ్మకు తండ్రి కూడా.',
        '1.0': 'ఆయన చూపు సారిస్తే సూర్యచంద్రులకు కాంతి నింపే సులక్షణుడు; నిలిచిన చోటనే సకల దేవతలను పుట్టించే దేవతల మూలం ఈయనే చూడండి.',
        '1.1': 'ఆయన మాట్లాడితే కోట్ల కొలది బ్రహ్మాండాలు పుట్టే గుణరాశి; ఆయన క్రమమైన ఊపిరుల నుండి సకల వేదాలు, అద్భుతాల సముద్రం వెలువడతాయి.',
        '1.2': 'ఎదుట ఉన్న మోహన రూపంతో ఆత్మలను పొంగించే ఘన పురుషుడు ఈయన; మావంటి శరణాగతులకు ఆశ్రయమైన అంగం శ్రీ వేంకటాధిపుడు ఈయనే.',
      },
    },
    'annamacharya-muddugare-yashoda': {
      summary: '“రత్న కీర్తన”: యశోద ముంగిట ముత్యం, గొల్లభామల అరచేతి మాణిక్యం, కంసుని సవాలుకు వజ్రం, గరుడపచ్చ, పగడం, గోమేధికం, వైడూర్యం, పుష్యరాగం, ఇంద్రనీలం, పాలకడలి దివ్యరత్నం అని కృష్ణుని వర్ణించి శ్రీ వేంకటాద్రి పద్మనాభునితో ముగిస్తుంది. కురింజి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'యశోద ముంగిట ముద్దైన ముత్యం ఇతడు; తిద్దలేని మహిమల దేవకీ సుతుడు.',
        '1.0': 'చిన్న గొల్లభామల అరచేతి మాణిక్యం, పట్టుపట్టే కంసునికి వజ్రం, మూడు లోకాల కాంతి గల గరుడ పచ్చ, మా చెంత ఉన్న చిన్ని కృష్ణుడు.',
        '1.1': 'రతికేళిలో రుక్మిణికి రంగు పెదవుల పగడం, గోవర్ధన పర్వతపు కొలతకు గోమేధికం, నిత్యం శంఖచక్రాల మధ్య వైడూర్యం, మాకు దిక్కై కాపాడే కమలాక్షుడు.',
        '1.2': 'కాళియుని పడగలపై కప్పిన పుష్యరాగం, ఏలే శ్రీ వేంకటాద్రి ఇంద్రనీలం, పాలకడలిలో విడువని దివ్య రత్నం, బాలుని వలె తిరిగే పద్మనాభుడు.',
      },
    },
    'annamacharya-jo-achyutananda': {
      summary: 'అన్నమయ్య అత్యంత ప్రసిద్ధ జోల పాట. “జో జో” పల్లవి కృష్ణుని నిద్రపుచ్చుతుంది; చరణాలు ఆయన బాల్యాన్ని, తరువాతి కార్యాలను చెబుతాయి: వెన్న దొంగతనం, గొల్లభామల ఫిర్యాదులు, గోవర్ధనం ఎత్తడం, కంస వధ. చివరి చరణం తాళ్ళపాక అన్నమయ్య పేరు చెప్పి అందరికీ మంగళం కోరుతుంది. కాపి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'జో అచ్యుతానంద, జో జో ముకుందా; రావే పరమానంద, రామ గోవిందా; జో జో, జో జో.',
        '1.0': 'నందుని ఇంటికి చేరి అందంగా, చంద్రముఖులు నీకు సేవ చేస్తుండగా, వారి ఇళ్ళలో ముచ్చటగా ఆడుతూ, మందల దొంగా, మా ముద్దు రంగా, జో జో.',
        '1.1': 'పాలకడలిలో పవళించావు; మునులకు అభయమిచ్చావు; వసుదేవునికి శుభంగా జన్మించావు; బాలుడవై ఉండి గోపాలుడవయ్యావు.',
        '1.2': 'గడ్డకట్టిన మీగడ తిని పిల్ల కోడలి మూతిపై పూశాడే; అత్త “తిన్నావా?” అని అడగగా విని, “ఇదే దొంగ, కొట్టు” అని గట్టిగా అన్నాడే.',
        '1.3': 'గొల్లల ఇళ్ళకు వేగంగా వెళ్ళి కుండల్లోని నెయ్యిని విస్తారంగా తాగావు. ఆడవారిని ఇలా ఆటపట్టించడం తగునా? ఇటువంటి చిలిపి పనులు చేయడం తగునా?',
        '1.4': 'రేపల్లె స్త్రీలంతా కోపంతో: “గోపమ్మా, నీ కొడుకు మా ఇళ్ళలో సాయంత్రమే వచ్చి మా మానాలను చెరిచాడు; ఏమందుమమ్మా?”',
        '1.5': 'ఒకని భార్యను తెచ్చి మరొకని పక్కన ఉంచి, తగాదాలు పెట్టి, దంపతులను పట్టుకొని, పగటి నాలుగు జాములు బాలుడై, మన్మథునిలా స్త్రీల చేయి పట్టి.',
        '1.6': 'గోవర్ధనమంతా గొడుగుగా పట్టి, గర్వించిన కంసుని పడగొట్టి, మధురాపురాన్ని చేజిక్కించుకొని ఠీవిగా ఏలిన దేవకీ పుత్రా.',
        '1.7': 'మన్మథుని తండ్రివైన మా ప్రియుడా, ఇటు రా; బంగారు గిన్నెలో పాలు పోశారు. నీవు దొంగవని ఆడవారు పొంగుతున్నారు; ముంగిట ఆడరా, మోహనాకారా, జో జో.',
        '1.8': 'తాళ్ళపాక అన్నమయ్య ఎంతో ప్రేమగా శృంగార రచనగా చెప్పిన ఈ జోల; సకల సంపదలు తగినట్లు నీవే అగుగాక; తిరుపతి మదనగోపాలునికి మంగళం, జో జో.',
      },
    },
    'annamacharya-nanati-batuku': {
      summary: 'వైరాగ్య గీతం: నిత్య జీవితం ఒక నాటకం; పుట్టుక, మరణం మాత్రమే నిజం; తినడం, కట్టడం, పాపపుణ్యాలు, కాలం గడవడం అన్నీ నాటకంలో భాగం; వేంకటేశ్వరుని ఏలుబడిలో ఆకాశాని కంటే పైన ఉన్నదే మోక్షం. రేవతి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'నానాటి బ్రతుకు నాటకం; కానక కన్నదే కైవల్యం.',
        '1.0': 'పుట్టడం నిజం, పోవడం నిజం; నడిమి పని నాటకం. ఎదుట ఉన్నది ప్రపంచం; చివరి కట్టకడపటిది కైవల్యం.',
        '1.1': 'తినే అన్నం, చుట్టే కోక నడిమి పని నాటకం. ఒడిలో కట్టుకున్న రెండు విధాల కర్మల గడి దాటినప్పుడే కైవల్యం.',
        '1.2': 'పాపం తెగదు, పుణ్యం తీరదు; నవ్వుతూ గడిచే కాలం నాటకం. పైన శ్రీ వేంకటేశ్వరుని ఏలుబడి; గగనానికి మీది కైవల్యం.',
      },
    },
    'annamacharya-tandanana-ahi': {
      summary: '“బ్రహ్మం ఒక్కటే”: నాట్య లయతో “తందనాన” పల్లవి తరువాత చరణాలు రాజు, సేవకుని నిద్ర ఒకటే, బ్రాహ్మణుడు, చండాలుడు నిలిచే భూమి ఒకటే, దేవతలకు, క్రిములకు కామసుఖం ఒకటే, ఆకలి ఒకటే, ఏనుగుపై కుక్కపై ఎండ ఒకటే, పుణ్యులకు పాపులకు వేంకటేశ్వరుని నామం ఒకటే అని చెబుతాయి. బౌళి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'తందనాన, ఆహి, తందనాన, పురె, తందనాన, భళా, తందనాన (నాట్య అక్షరాలు). బ్రహ్మం ఒక్కటే, పరబ్రహ్మం ఒక్కటే.',
        '1.0': 'ఇందులో స్థిరమైన హెచ్చుతగ్గులు లేవు; అందరికీ శ్రీహరే అంతరాత్మ. ఇందులో జంతుకులమంతా ఒకటే; అందరికీ శ్రీహరే అంతరాత్మ.',
        '1.1': 'పూర్ణ వైభవ రాజు నిద్రించే నిద్ర ఒకటే; ప్రక్కనే ఉన్న సేవకుని నిద్ర కూడా అదే. గొప్ప బ్రాహ్మణుడు తొక్కే భూమి ఒకటే; చండాలుడు తొక్కే భూమి కూడా అదే.',
        '1.2': 'అనుంగు దేవతల కామసుఖం, గొప్ప కీటక పశువుల కామసుఖం ఒకటే; పగలు రాత్రి ధనవంతునికి ఒకటే, నిరుపేదకు కూడా అవే.',
        '1.3': 'మంచి అన్నం తీసుకునే ఆకలి ఒకటే; చెడు అన్నం తినే ఆకలి కూడా అదే. దుర్గంధాలపై వీచే గాలి ఒకటే; పరిమళంపై వీచే గాలి కూడా అదే.',
        '1.4': 'ఏనుగుపై కాసే ఎండ ఒకటే; నేలపై కుక్కపై పడే ఎండ కూడా అదే. మిక్కిలి పుణ్యులను, పాపకర్ములను సమంగా కాపాడే శ్రీ వేంకటేశ్వరుని నామం ఒక్కటే.',
      },
    },
    'annamacharya-vinaro-bhagyamu': {
      summary: '“వినరో భాగ్యము, విష్ణుకథ!” విష్ణుకథే నిత్యవిధులలోని వేదం, నారదాదులు వీధివీధులా పాడినది, వ్యాసుడు స్తుతించినది, సంకీర్తనారూపంలో నివాసం, ఇప్పుడు గొల్లభామలు చిలుకుతుండగా వ్యాపించిన వేంకటేశ్వరుని నామం. శుద్ధ ధన్యాసి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'వినండి ఈ భాగ్యం, విష్ణుకథ; ఇదే వెనుక బలం, విష్ణుకథ.',
        '1.0': 'ఆది నుండి సంధ్యాది విధుల్లో వేదమైనది విష్ణుకథ; నారదాదుల చేత వీధివీధుల్లో నాదించేది విష్ణుకథ.',
        '1.1': 'వేదవ్యాసులు విడువకుండా చెప్పిన ప్రసిద్ధ పావన విష్ణుకథ; సంకీర్తనగా నివాసమైనది; వెదకిన చోటనే ఉన్నది విష్ణుకథ.',
        '1.2': 'గొల్లభామలు ఉత్సాహంగా మజ్జిగ చిలుకుతుండగా అంతటా వ్యాపించినది విష్ణుకథ; ఇదిగో శ్రీ వేంకటేశ్వరుని నామమైన ఈ విష్ణుకథ పొంగి పొరలింది.',
      },
    },
    'annamacharya-adivo-alladivo': {
      summary: 'తిరుమల చేరినప్పటి గీతం: “అదిగో అల్లదిగో శ్రీహరి నివాసం”, వేయి పడగల శేషుని పడగలతో ఏర్పడిన కొండ, దేవతల నిజ నివాసం, నేలలో దాగిన నిధి, కైవల్యం, సకల సంపదలను ఇచ్చే శిఖరం. మధ్యమావతి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'అదిగో అల్లదిగో శ్రీహరి నివాసం, పదివేల శేషుల పడగలతో నిండినది.',
        '1.0': 'అదే వేంకటాచలం, అన్నింటికంటే ఉన్నతం; బ్రహ్మాదులకూ అపురూపం; మునులందరికీ నిత్య నివాసం; అదిగో చూడండి, మొక్కండి, ఆనందమయం.',
        '1.1': 'దగ్గరలో ఆ శేషాచలం; ఆకాశంలోని దేవతల నిజ నివాసం; ఎదుట మూలన ఉన్న ధనం; బంగారు శిఖరాల బ్రహ్మమయం.',
        '1.2': 'ఆ వేంకటనగమే కైవల్యపదం; శ్రీ వేంకటపతికి సిరులైనవి; భావిస్తే సకల సంపద రూపం అదే; పావనాలన్నిటికీ పావనమయం.',
      },
    },
    'annamacharya-kondalalo-nelakonna': {
      summary: 'కొండల్లో కొలువైన కోనేటి రాయని భక్తి గీతం: కొండంత వరాలు ఇచ్చేవాడు, కుమ్మర భక్తుడు కురువ నంబి అడిగిన వరాలిచ్చినవాడు, రాజు తొండమాన్ పిలిచిన చోటికి వచ్చినవాడు, అనంతాళ్వారుకై మట్టి మోసినవాడు, తిరుమల నంబితో ప్రేమగా మాట్లాడినవాడు, కంచి నంబిని రప్పించినవాడు. హిందోళ రాగంలో పాడతారు.',
      verses: {
        '0.0': 'కొండల్లో నెలకొన్న కోనేటి రాయడు వాడు; కొండంత వరాలను గుప్పించేవాడు.',
        '1.0': 'కుమ్మర భక్తుడైన కురువరతి నంబి “ఇమ్ము” అన్న వరాలన్నీ ఇచ్చినవాడు; పోరాడిన తొండమాన్ చక్రవర్తి “రమ్ము” అన్న చోటికి వచ్చి నమ్మినవాడు.',
        '1.1': 'నిజమైన ఉత్సాహంతో అనంతాళ్వారుకై వెట్టి చాకిరీగా మట్టి మోసినవాడు; ప్రేమ ఒలుకుతూ తిరుమల నంబితో రోజూ మాట్లాడి నొచ్చుకున్నవాడు.',
        '1.2': 'కంచిలో ఉన్న తిరుకచ్చి నంబిపై కరుణించి తన వద్దకు రప్పించినవాడు; ఎంచి ఎక్కుడైన వేంకటేశుడు మనకు మంచివాడై కరుణతో పాలించినవాడు.',
      },
    },
    'annamacharya-narayanate-namo-namo': {
      summary: 'నారాయణునికి ఆయన అనేక నామాలతో నమస్కారాలు: మురహర, ముకుంద, మాధవ, గరుడగమన, పద్మనాభ, నరసింహ, జలధిశయన, గోపవధూవల్లభ; చివరికి వేదోద్ధర వేంకటనాయక నాదప్రియ. మధ్యమావతి రాగంలో పాడతారు.',
      verses: {
        '0.0': 'నారాయణా, నీకు నమో నమో; నారద సన్నుతా, నమో నమో.',
        '1.0': 'మురహర, భవహర, ముకుంద, మాధవ, గరుడగమన, పంకజనాభ; పరమ పురుష, భవబంధ విమోచన, నరమృగ శరీర, నమో నమో.',
        '1.1': 'జలధిశయన, రవిచంద్ర విలోచన, పద్మజుడు స్తుతించే చరణద్వయం; బలిబంధన, గోపవధూవల్లభ, నళినోదర, నీకు నమో నమో.',
        '1.2': 'ఆదిదేవ, సకలాగమ పూజిత, యాదవ కుల మోహనరూప; వేదోద్ధర, శ్రీ వేంకటనాయక, నాదప్రియ, నీకు నమో నమో.',
      },
    },
    'annamacharya-ksheerabdi-kanyakaku': {
      summary: 'పాలకడలి కుమార్తె శ్రీ మహాలక్ష్మికి నీరాజన గీతం: ఆమె కమల ముఖం, వక్షం, కురులు, చేతులు, పాదాలు, తొడలు, నడుము, నాభికి హారతులు; చివరికి శ్రీ వేంకటేశుని పట్టపురాణి అలమేలుమంగకు. వివాహాల్లో, లక్ష్మీ పూజలో పాడతారు.',
      verses: {
        '0.0': 'పాలకడలి కన్యకు, శ్రీ మహాలక్ష్మికి, కమలవాసినికి నీరాజనం.',
        '1.0': 'పద్మాక్షి ముఖానికి, చక్రవాక పక్షుల వంటి వక్షానికి, కర్పూర నీరాజనం.',
        '1.1': 'తుమ్మెద నల్లని కురుల ముడికి, కరకమలాలకు, నిలువు మాణిక్యాల నీరాజనం.',
        '1.2': 'చిగురుటాకుల వంటి పాదాలకు, అరటి దవ్వల వంటి తొడలకు, ఎడతెగని ముత్యాల నీరాజనం.',
        '1.3': 'అరుదైన జఘనానికి, ఆ సతి నాభికి, ప్రేమతో నానా వర్ణ నీరాజనం.',
        '1.4': 'పగటి వేళ శ్రీ వేంకటేశుని పట్టపురాణియై వెలిగే సతి కళలకు నీరాజనం.',
        '1.5': 'లోకంలో అలమేలుమంగ చక్కదనాలన్నిటికీ నిండైన నిజ శోభనపు నీరాజనం.',
      },
    },
    'om-jai-jagdish-hare': {
      summary: 'దాదాపు ప్రతి పూజ చివర పాడే హిందీలోని అత్యంత ప్రసిద్ధ హారతి: జగదీశునికి ఎనిమిది చిన్న పద్యాలు, ప్రతిదాని తరువాత పల్లవి “ఓం జయ జగదీశ హరే”. భక్తుల సంకటాలను క్షణంలో తొలగించమని కోరి, ఆయనను తల్లిదండ్రులుగా, ఏకైక శరణంగా, అంతర్యామిగా పిలుస్తూ, తన మూర్ఖత్వాన్ని అంగీకరించి శ్రద్ధాభక్తులు పెంచమని వేడుకుంటుంది. తరువాతి ముద్రణల రెండు అదనపు పద్యాలు చివర ఇవ్వబడ్డాయి.',
      verses: {
        '0.0': 'ఓం, జగదీశ్వరుడైన హరికి జయం; నా స్వామి జగదీశ హరికి జయం. భక్తుల సంకటాలను, సేవకుల సంకటాలను ఆయన క్షణంలో తొలగిస్తాడు.',
        '1.0': 'ఆయనను ధ్యానించినవాడు ఫలం పొందుతాడు; మనసులోని దుఃఖం నశిస్తుంది, ఇంటికి సుఖసంపదలు వస్తాయి, శరీర బాధ తొలగిపోతుంది.',
        '1.1': 'నీవే నా తల్లిదండ్రులు; నేను ఎవరి శరణు పొందాలి? నీవు తప్ప మరెవరూ లేరు, ఎవరిపై ఆశ పెట్టుకోవాలి?',
        '1.2': 'నీవు పూర్ణ పరమాత్మవు, నీవు అంతర్యామివి; పరబ్రహ్మ, పరమేశ్వరా, నీవు అందరికీ ప్రభువు.',
        '1.3': 'నీవు కరుణా సాగరుడవు, నీవు పోషకుడవు; నేను మూర్ఖుడను, దుష్టుడను, కోరికలతో నిండినవాడను; నేను సేవకుడను, నీవు ప్రభువు: భర్తా, కరుణించు.',
        '1.4': 'నీవు ఒక్కడివి, ఇంద్రియాలకు అందనివాడివి, అందరి ప్రాణనాథుడివి. దయామయా, మందబుద్ధినైన నేను నిన్ను ఏ విధంగా చేరగలను?',
        '1.5': 'దీనబంధూ, దుఃఖహర్తా, నీవే నా ప్రభువు, నా రక్షకుడవు. నీ చేయి ఎత్తి నన్ను నీ శరణులోకి తీసుకో; నేను నీ గుమ్మం వద్ద పడి ఉన్నాను.',
        '1.6': 'విషయ వికారాలను తొలగించు, దేవా, పాపాలను హరించు; శ్రద్ధాభక్తులను, సాధు సేవను పెంచు.',
        '2.0': 'శ్రీ జగదీశుని ఈ హారతిని ఎవరు పాడుతారో వారు సుఖసంపదలు పొందుతారని శివానంద స్వామి అంటున్నారు.',
        '2.1': 'తనువు, మనసు, ధనం, అన్నీ నీవే; నీదైనదాన్నే నీకు అర్పిస్తున్నాను, నాదేమున్నది?',
      },
    },
    'hanuman-ashtak': {
      summary: 'హిందీలో ఎనిమిది పద్యాలు, ప్రతి దాని చివర పల్లవి: “హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?” సూర్యుని మింగడం, సుగ్రీవ రక్షణ, సీతాన్వేషణ, లక్ష్మణునికి సంజీవిని తేవడం, రామలక్ష్మణులను నాగపాశం నుండి విడిపించడం, అహిరావణ వధను స్మరించి, మా సంకటాలన్నీ తొలగించమని కోరుతుంది. మంగళ, శనివారాల్లో, తరచు హనుమాన్ చాలీసా తరువాత పఠిస్తారు.',
      verses: {
        '0.0': 'బాల్యంలో నీవు సూర్యుని మింగగా మూడు లోకాలు చీకటయ్యాయి; లోకం భయపడింది, ఈ సంకటం ఎవరూ తొలగించలేకపోయారు. దేవతలు వచ్చి ప్రార్థించగా సూర్యుని విడిచి కష్టం తీర్చావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.1': 'వాలి భయంతో వానరరాజు కొండపై ఉండి మహాప్రభువు వచ్చే దారి చూస్తున్నాడు. మహాముని చకితుడై శాపమిచ్చాడు; ఏమి ఆలోచించాలి? నీవు బ్రాహ్మణ రూపం ధరించి మహాప్రభువును తెచ్చి నీ దాసుని శోకం తొలగించావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.2': 'అంగదునితో సీతను వెతకడానికి వెళ్ళిన వానరులతో సుగ్రీవుడు: “వార్త తేకుండా ఇక్కడికి వస్తే బ్రతకరు” అన్నాడు. అందరూ సముద్ర తీరంలో వెతికి అలసిపోయారు; అప్పుడు నీవు సీత వార్త తెచ్చి ప్రాణాలు కాపాడావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.3': 'రావణుడు రాక్షసీల ద్వారా సీతను బాధించాడు; ఆ సమయంలో మహాప్రభూ హనుమా, నీవు వెళ్ళి గొప్ప రాక్షసులను సంహరించావు. సీత అశోక వృక్షాన్ని అగ్ని అడిగినప్పుడు నీవు ప్రభువు ఉంగరమిచ్చి ఆమె శోకం తొలగించావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.4': 'రావణ పుత్రుని బాణం లక్ష్మణుని రొమ్ముకు తగిలి ఆయన ప్రాణాలు వదలగా, నీవు వైద్యుడు సుషేణుని ఇంటితో సహా తెచ్చి ద్రోణ పర్వతాన్ని పెకలించావు; సంజీవిని తెచ్చి చేతిలో ఇచ్చి లక్ష్మణుని ప్రాణం కాపాడావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.5': 'అప్పుడు రావణుడు అదృశ్య యుద్ధం చేసి అందరి శిరస్సులపై నాగపాశం వేశాడు; శ్రీ రఘునాథునితో సహా సేన అంతా మోహంలో పడింది, ఇది పెద్ద సంకటం. హనుమా, నీవు పక్షిరాజు గరుత్మంతుని తెచ్చి బంధాలు తెంపి గొప్ప భయం తొలగించావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.6': 'అహిరావణుడు తమ్మునితో సహా రఘునాథుని పాతాళానికి తీసుకుపోయి దేవికి బలి ఇవ్వడానికి అందరూ కలిసి ఆలోచించినప్పుడు నీవు సహాయంగా వెళ్ళి అహిరావణుని సేనతో సహా సంహరించావు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '0.7': 'నీవు దేవతలకు గొప్ప కార్యాలు చేశావు; వీర మహాప్రభూ, ఆలోచించు: పేదవాడినైన నా ఏ సంకటం నీవు తొలగించలేనిది? హనుమా, మాకు ఏ సంకటం ఉన్నా వెంటనే తొలగించు. హనుమా, నీ పేరు సంకటమోచన అని లోకంలో ఎవరికి తెలియదు?',
        '1.0': 'ఎర్రని దేహం, ఎరుపుతో మెరిసే, ఎర్రని తోక ధరించిన, వజ్ర దేహుడు, దానవులను దలించే శూర కపికి జయ జయ జయ.',
      },
    },
    'shiv-chalisa': {
      summary: 'హిందీలో శివుని నలభై చౌపాయిల స్తుతి: చంద్రుడు, గంగ, నాగకుండలాలు, త్రిశూలంతో ఉన్న రూపం; తారక, జలంధర, త్రిపురుల నుండి దేవతలను కాపాడడం, సముద్ర మథన విషం; లంకకు ముందు రాముడు చేసిన పూజ; కష్టంలో సహాయం కోరిక; త్రయోదశినాడు పఠించే ఫలం. సోమవారాల్లో, శ్రావణంలో పఠిస్తారు.',
      verses: {
        '0.0': 'గిరిజా పుత్రుడు, మంగళ మూలం, జ్ఞాని అయిన గణేశునికి జయం; అయోధ్యాదాసు అంటున్నాడు: అభయ వరాన్ని ఇవ్వు.',
        '1.0': 'గిరిజాపతీ, దీనులపై దయగలవాడా, సదా సంతులను పాలించేవాడా, జయం.',
        '1.1': 'నీ నుదుటిపై చంద్రుడు శోభిస్తాడు; చెవులలో నాగఫణ కుండలాలు.',
        '1.2': 'నీ దేహం ధవళం, శిరస్సు నుండి గంగ ప్రవహిస్తుంది; కపాలమాల ధరించి, దేహానికి భస్మం పూసుకున్నావు.',
        '1.3': 'నీ వస్త్రం పులి చర్మం; ఆ శోభను చూసి నాగులు సైతం మోహితమవుతాయి.',
        '1.4': 'మైనా ముద్దుల కూతురు పార్వతి నీ ఎడమ భాగంలో అపూర్వ శోభతో ఉంది.',
        '1.5': 'చేతిలో త్రిశూలం గొప్ప శోభనిస్తూ ఎల్లప్పుడూ శత్రువులను నాశనం చేస్తుంది.',
        '1.6': 'నంది, గణేశుడు అక్కడ సముద్రం మధ్యలోని కమలాల వలె శోభిస్తారు.',
        '1.7': 'కార్తికేయుడు, శ్యామవర్ణుడు, గణాధిపతి; ఈ శోభను ఎవరూ వర్ణించలేరు.',
        '1.8': 'దేవతలు ఎప్పుడు వెళ్ళి పిలిచినా అప్పుడే నీవు వారి దుఃఖాన్ని తొలగించావు.',
        '1.9': 'తారకుడు పెద్ద ఉపద్రవం చేసినప్పుడు దేవతలంతా కలిసి నిన్ను ప్రార్థించారు.',
        '1.10': 'వెంటనే నీవు షణ్ముఖుని పంపావు; ఆయన రెప్పపాటులో అతనిని సంహరించాడు.',
        '1.11': 'జలంధర అసురుని నీవే సంహరించావు; నీ సుకీర్తి లోకమంతా తెలుసు.',
        '1.12': 'త్రిపురాసురుడు యుద్ధం చేసినప్పుడు నీవు కృపతో అందరినీ కాపాడావు.',
        '1.13': 'భగీరథుడు ఘోర తపస్సు చేశాడు; పురారీ, అతనికి చేసిన పూర్వ ప్రతిజ్ఞను నెరవేర్చావు.',
        '1.14': 'దాతలలో నీ వంటి వారెవరూ లేరు; సేవకులు సదా నిన్ను స్తుతిస్తారు.',
        '1.15': 'వేదాలు నీ నామ మహిమను గానం చేస్తాయి; నీవు వర్ణనాతీతుడవు, అనాదివి; నీ రహస్యాన్ని ఎవరూ తెలుసుకోలేదు.',
        '1.16': 'సముద్ర మథనంలో విష జ్వాల పుట్టినప్పుడు దేవతలు, అసురులు మండుతూ విలవిలలాడారు.',
        '1.17': 'అక్కడ నీవు దయతో సహాయం చేశావు; అప్పటి నుండి నీలకంఠుడనే పేరు వచ్చింది.',
        '1.18': 'శ్రీరామచంద్రుడు నిన్ను పూజించి లంకను గెలిచి విభీషణునికి ఇచ్చినప్పుడు,',
        '1.19': 'ఆయన వెయ్యి కమలాలు అర్పిస్తుండగా పురారీ, నీవు ఆయనను పరీక్షించావు.',
        '1.20': 'నీవు ఒక కమలాన్ని దాచావు; కమలనయనుడైన ఆయన తన కన్నుతోనే పూజించదలచాడు.',
        '1.21': 'ఆయన కఠిన భక్తిని చూసి శంకరుడు సంతోషించి కోరిన వరం ఇచ్చాడు.',
        '1.22': 'జయ జయ జయ, అనంతా, అవినాశీ, అందరి హృదయంలో నివసించి కృప చూపేవాడా.',
        '1.23': 'దుష్టులంతా రోజూ నన్ను బాధిస్తున్నారు; తిరుగుతూనే ఉన్నాను, నాకు శాంతి లేదు.',
        '1.24': 'కాపాడు కాపాడు, నాథా, పిలుస్తున్నాను; ఈ సమయంలో వచ్చి నన్ను ఉద్ధరించు.',
        '1.25': 'త్రిశూలం పట్టి నా శత్రువులను సంహరించు; ఈ సంకటం నుండి నన్ను రక్షించు.',
        '1.26': 'తల్లి, తండ్రి, సోదరులు అందరూ ఉన్నారు; కానీ సంకటంలో ఎవరూ పట్టించుకోరు.',
        '1.27': 'స్వామీ, నాకు ఏకైక ఆశ నీవే; వచ్చి నా పెద్ద సంకటాన్ని తొలగించు.',
        '1.28': 'నీవు పేదలకు ఎల్లప్పుడూ ధనం ఇస్తావు; ఎవరు అడిగినా ఫలం పొందుతారు.',
        '1.29': 'నీ స్తుతి ఎలా చేయాలి? నాథా, ఇప్పుడు నా తప్పును క్షమించు.',
        '1.30': 'శంకరా, సంకటాలను నశింపజేసేవాడా, మంగళ కారణుడా, విఘ్న వినాశకా.',
        '1.31': 'యోగులు, యతులు, మునులు నిన్ను ధ్యానిస్తారు; శారద, నారదులు నీకు శిరస్సు వంచుతారు.',
        '1.32': 'నమో నమో, జయ నమః శివాయ; బ్రహ్మాది దేవతలకూ నీ అంతు తెలియదు.',
        '1.33': 'ఎవరు మనసు పెట్టి ఇది పఠిస్తారో వారికి శంభుని సహాయం కలుగుతుంది.',
        '1.34': 'అప్పుల్లో ఉన్నవాడు ఇది పఠిస్తే అప్పు నుండి విముక్తుడవుతాడు.',
        '1.35': 'పుత్రుని కోరేవానికి తప్పక శివుని అనుగ్రహం కలుగుతుంది.',
        '1.36': 'త్రయోదశి నాడు పండితుని పిలిచి శ్రద్ధగా హోమం చేయించాలి.',
        '1.37': 'ఎల్లప్పుడూ త్రయోదశి వ్రతం చేసేవాని శరీరంలో కష్టం ఉండదు.',
        '1.38': 'ధూపం, దీపం, నైవేద్యం సమర్పించి శంకరుని ముందు ఇది పఠించాలి.',
        '1.39': 'జన్మజన్మల పాపాలు నశించి అంతమున శివపురంలో స్థానం లభిస్తుంది.',
        '1.40': 'అయోధ్యాదాసు అంటున్నాడు: నా ఆశ నీపైనే; నా దుఃఖాలన్నీ తెలిసి తొలగించు.',
        '2.0': 'ప్రతి ఉదయం నియమంగా ఈ చాలీసా పఠిస్తున్నాను; జగదీశా, నా మనోరథాలు నెరవేర్చు.',
        '2.1': 'హేమంత ఋతువులో మార్గశిర షష్ఠి నాడు, సంవత్ అరవై నాలుగులో, శివుని స్తుతి ఈ చాలీసా అందరి క్షేమం కోసం పూర్తయింది.',
      },
    },
    'durga-chalisa': {
      summary: 'అమ్మవారి నలభై చౌపాయిల హిందీ స్తుతి: ఆమె తేజోరూపం, సరస్వతి, నృసింహ శక్తి, లక్ష్మి, అన్నపూర్ణ, కాళి, దశమహావిద్యల రూపాలు, శుంభ నిశుంభ రక్తబీజ మహిషాసుర వధ, శంకరాచార్యుని పశ్చాత్తాపం, ప్రేమతో పాడేవారికి హామీ. మంగళవారం, శుక్రవారం, నవరాత్రిలో పఠిస్తారు.',
      verses: {
        '0.0': 'సుఖమిచ్చే దుర్గకు నమో నమః; దుఃఖం హరించే దుర్గకు నమో నమః.',
        '0.1': 'నీ జ్యోతి నిరాకారం; దాని వెలుగు మూడు లోకాల్లో వ్యాపించింది.',
        '0.2': 'నుదుట చంద్రుడు, విశాల ముఖం, ఎర్రని కన్నులు, భయంకర కనుబొమలు.',
        '0.3': 'అమ్మవారి రూపం ఎంతో మనోహరం; దర్శించే జనులు గొప్ప సుఖం పొందుతారు.',
        '0.4': 'నీవు లోకశక్తిని సృష్టించి, పోషణ కోసం అన్నం, ధనం ఇచ్చావు.',
        '0.5': 'అన్నపూర్ణవై లోకాన్ని పోషించావు; నీవే ఆది సుందరి బాల.',
        '0.6': 'ప్రళయకాలంలో అన్నింటినీ నశింపజేసేది నీవే; నీవు గౌరివి, శివ శంకరుని ప్రియురాలివి.',
        '0.7': 'శివుడు, యోగులు నీ గుణాలను గానం చేస్తారు; బ్రహ్మ, విష్ణువులు నిత్యం నిన్ను ధ్యానిస్తారు.',
        '0.8': 'సరస్వతి రూపం ధరించి సద్బుద్ధి ఇచ్చి ఋషి మునులను ఉద్ధరించావు.',
        '0.9': 'అమ్మా, నృసింహ రూపం ధరించి స్తంభాన్ని చీల్చి ప్రత్యక్షమయ్యావు.',
        '0.10': 'ప్రహ్లాదుని రక్షించి హిరణ్యాక్షుని (హిరణ్యకశిపుని) స్వర్గానికి పంపావు.',
        '0.11': 'లోకంలో లక్ష్మీ రూపం ధరించి శ్రీ నారాయణుని అంగంలో లీనమయ్యావు.',
        '0.12': 'పాలకడలిలో విహరిస్తావు; దయా సముద్రమా, నా మనోరథం తీర్చు.',
        '0.13': 'హింగులాజ్‌లో నీవే భవానివి; నీ అపార మహిమను వర్ణించలేము.',
        '0.14': 'మాతంగి, ధూమావతి, భువనేశ్వరి, బగళ: నీవే సుఖదాతవు.',
        '0.15': 'శ్రీ భైరవి, జగత్తును తరింపజేసే తార, భవ దుఃఖాన్ని తొలగించే ఛిన్నమస్త.',
        '0.16': 'సింహం నీ వాహనం, భవానీ; వీర లాంగురుడు ముందుగా దారి చూపుతూ నడుస్తాడు.',
        '0.17': 'చేతిలో కపాల పాత్ర, ఖడ్గం ప్రకాశిస్తాయి; వాటిని చూసి కాలుడు కూడా భయంతో పారిపోతాడు.',
        '0.18': 'అస్త్రాలు, త్రిశూలం శోభిస్తాయి; వాటితో శత్రువుల హృదయంలో బాధ పుడుతుంది.',
        '0.19': 'నగరకోట్‌లో నీవు కొలువై ఉన్నావు; మూడు లోకాల్లో నీ డంకా మోగుతుంది.',
        '0.20': 'శుంభ నిశుంభ దానవులను సంహరించావు; రక్తబీజుని, శంఖులను నాశనం చేశావు.',
        '0.21': 'మహిషాసురుడు చాలా గర్విష్ఠి; అతని పాప భారంతో భూమి కలవరపడింది.',
        '0.22': 'భయంకర కాళికా రూపం ధరించి అతనిని సేనతో సహా సంహరించావు.',
        '0.23': 'సంతులపై గాఢ సంకటం పడినప్పుడల్లా అమ్మా, నీవు అప్పుడల్లా సహాయం చేశావు.',
        '0.24': 'అమరపురి, ఇతర లోకాల్లో నీ మహిమతో అందరూ శోకరహితులై ఉంటారు.',
        '0.25': 'జ్వాల (జ్వాలాముఖి)లో నీ జ్యోతి ఉంది; స్త్రీ పురుషులు సదా నిన్ను పూజిస్తారు.',
        '0.26': 'ప్రేమ భక్తితో నీ యశస్సు పాడేవానికి దుఃఖం, దారిద్ర్యం దగ్గరకు రావు.',
        '0.27': 'మనసు నిలిపి నిన్ను ధ్యానించేవాడికి జన్మమరణాలు తొలగుతాయి.',
        '0.28': 'యోగులు, దేవతలు, మునులు పిలిచి చెబుతారు: నీ శక్తి లేనిదే యోగం కాదు.',
        '0.29': 'శంకరాచార్యులు తపస్సు చేసి కామక్రోధాలను జయించారు.',
        '0.30': 'రాత్రింబవళ్ళు శంకరుని ధ్యానించారు; ఏ కాలంలోనూ నిన్ను స్మరించలేదు.',
        '0.31': 'శక్తి రూపం రహస్యం తెలియలేదు; శక్తి పోయినప్పుడు మనసులో పశ్చాత్తాపపడ్డారు.',
        '0.32': 'శరణు చొచ్చి నీ కీర్తిని పొగిడారు: జయ జయ జయ జగదంబా భవానీ.',
        '0.33': 'ఆది జగదంబ ప్రసన్నురాలై ఆలస్యం చేయక శక్తి ఇచ్చింది.',
        '0.34': 'అమ్మా, నన్ను పెద్ద కష్టం చుట్టుముట్టింది; నీవు లేకుండా నా దుఃఖం ఎవరు తొలగిస్తారు?',
        '0.35': 'ఆశ, తృష్ణ నన్ను ఎంతో బాధిస్తున్నాయి; మూర్ఖ శత్రువులు నన్ను భయపెడుతున్నారు.',
        '0.36': 'మహారాణీ, నా శత్రువులను నాశనం చెయ్యి; భవానీ, ఏకాగ్ర చిత్తంతో నిన్ను స్మరిస్తున్నాను.',
        '0.37': 'దయామయీ అమ్మా, కృప చూపు; ఋద్ధిసిద్ధులు ఇచ్చి నన్ను ధన్యుని చెయ్యి.',
        '0.38': 'జీవించి ఉన్నంత వరకు నీ దయ ఫలం పొందుతూ, నీ యశస్సు సదా వినిపిస్తాను.',
        '0.39': 'దుర్గా చాలీసా పాడేవాడు అన్ని సుఖాలు అనుభవించి పరమపదం పొందుతాడు.',
        '0.40': 'దేవీదాసు శరణుచొచ్చినవాడని తెలిసి కృప చూపు, జగదంబా భవానీ.',
        '1.0': 'శరణాగతుని రక్షిస్తే భక్తుడు నిర్భయంగా ఉంటాడు; నేను నీ శరణు వచ్చాను, అమ్మా, నన్ను ఒడిలోకి తీసుకో.',
      },
    },
    'bajrang-baan': {
      summary: 'భయం, కష్టాల మీదకు సంధించిన “బాణం” లాగా హనుమంతునికి హిందీలో చేసిన తీవ్ర ప్రార్థన: ఆయన సముద్ర లంఘనం, సురస, లంకిణులతో కలయిక, లంకాదహనం, లక్ష్మణ రక్షణను గుర్తుచేసి, రాముని పేరిట వెంటనే వచ్చి భూత ప్రేతాలను, శత్రువులను, దుఃఖాన్ని తరిమివేయమని కోరుతుంది. శ్రద్ధతో పఠించేవారికి హామీతో ముగుస్తుంది.',
      verses: {
        '0.0': 'దృఢ ప్రేమ విశ్వాసాలతో వినయంగా సేవించేవాని కార్యాలన్నీ హనుమంతుడు శుభంగా నెరవేరుస్తాడు.',
        '1.0': 'సంతుల హితకారి హనుమంతునికి జయం; ప్రభూ, మా మనవి ఆలకించు.',
        '1.1': 'సేవకుని పనిలో ఆలస్యం చేయకు; పరుగెత్తి వచ్చి గొప్ప సుఖమివ్వు.',
        '1.2': 'సముద్రాన్ని దూకి దాటినట్లు, విస్తరిస్తున్న సురస నోటిలో ప్రవేశించినట్లు,',
        '1.3': 'ముందుకు వెళ్ళి లంకిణి ఆపినప్పుడు తన్ని ఆమెను సురలోకానికి పంపినట్లు,',
        '1.4': 'విభీషణునికి వెళ్ళి సుఖమిచ్చి, సీతను చూసి పరమానందం పొందినట్లు,',
        '1.5': 'తోటను పెకలించి సముద్రంలో ముంచి, అతి వేగంతో యముడినే భయపెట్టినట్లు,',
        '1.6': 'అక్షయకుమారుని చంపి, తోకతో చుట్టి లంకను కాల్చినట్లు,',
        '1.7': 'లంక లక్కలా కాలిపోయింది; సురపురంలో జయజయ ధ్వనులు వెలువడ్డాయి,',
        '1.8': 'ఇప్పుడు స్వామీ, ఆలస్యం ఎందుకు? అంతర్యామీ, కృపచూపు.',
        '1.9': 'లక్ష్మణునికి ప్రాణదాతకు జయ జయ; త్వరగా నా దుఃఖాన్ని అంతమొందించు.',
        '1.10': 'పర్వతధారికి జయం; సుఖసాగరునికి జయం; దేవతా సమూహపు సమర్థ వీరునికి జయం.',
        '1.11': 'ఓం హను హను హను హనుమంతా, పట్టుదల గలవాడా; శత్రువులను వజ్రపు మేకులతో కొట్టు.',
        '1.12': 'గద, వజ్రం తీసుకొని శత్రువులను సంహరించు; మహారాజా ప్రభూ, నీ దాసుని రక్షించు.',
        '1.13': 'ఓంకార హుంకార మహాప్రభూ, పరుగెత్తి రా; వజ్రం గదతో ఆలస్యం చేయకు.',
        '1.14': 'ఓం హ్రీం హ్రీం హ్రీం కపీశా; ఓం హుం హుం హుం, శత్రువు రొమ్ముపై, తలపై కొట్టు.',
        '1.15': 'హరి ప్రమాణంతో సత్యమగుగాక; రామదూతా, పరుగెత్తి సంహరించు.',
        '1.16': 'అగాధ హనుమంతునికి జయ జయ జయ; నీ దాసుడు ఏ అపరాధానికి దుఃఖపడుతున్నాడు?',
        '1.17': 'పూజ, జపం, తపస్సు, నియమాలు, ఆచారాలు: నీ దాసునికి ఏమీ తెలియవు.',
        '1.18': 'అడవి, ఉపవనం, దారి, కొండ, ఇల్లు ఎక్కడైనా నీ బలంతో మేము భయపడము.',
        '1.19': 'చేతులు జోడించి పాదాలపై పడతాను; ఈ సమయంలో ఇంకెవరిని పిలవాలి?',
        '1.20': 'అంజనీ కుమారా, బలవంతా, శంకరసుతా, ధీరుడైన హనుమంతునికి జయం.',
        '1.21': 'భయంకర ముఖం, కాల కుల నాశకుడు, రాముని సహాయంతో సదా రక్షకుడు.',
        '1.22': 'భూత, ప్రేత, పిశాచ, నిశాచర, అగ్ని, వేతాళ, కాల, మారి:',
        '1.23': 'వీరిని సంహరించు, రాముని ఆన; నాథా, నీ నామ మర్యాద కాపాడు.',
        '1.24': 'జనకసుత నిన్ను హరి దాసుడన్నది; ఆమె ఆన, ఆలస్యం చేయకు.',
        '1.25': 'ఆకాశంలో జయజయ ధ్వనులు వినిపిస్తాయి; స్మరిస్తే సహించలేని దుఃఖం నశిస్తుంది.',
        '1.26': 'నీ చరణాల శరణు తీసుకొని చేతులు జోడించి వేడుతున్నాను; ఈ సమయంలో ఇంకెవరిని పిలవాలి?',
        '1.27': 'లే లే, పద; రాముని ఆన; చేతులు జోడించి కాళ్ళపై పడతాను.',
        '1.28': 'ఓం చం చం చం చం చపల గమనుడా; ఓం హను హను హను హనుమంతా.',
        '1.29': 'ఓం హం హం చంచల కపి హుంకరిస్తాడు; ఓం సం సం ఖల దళాలు భయంతో పారిపోతాయి.',
        '1.30': 'నీ జనులను వెంటనే రక్షించు; స్మరించగానే మాకు ఆనందం.',
        '1.31': 'ఈ బజరంగ బాణం ఎవరిని తాకుతుందో, వానిని ఇక ఎవరు కాపాడతారు?',
        '1.32': 'బజరంగ బాణం పఠించేవాని ప్రాణాన్ని హనుమంతుడు రక్షిస్తాడు.',
        '1.33': 'ఈ బజరంగ బాణం జపించేవానికి భూత ప్రేతాలన్నీ వణుకుతాయి.',
        '1.34': 'ధూపం వేసి ఎల్లప్పుడూ జపించేవాని శరీరంలో కష్టం ఉండదు.',
        '2.0': 'దృఢ ప్రేమతో కపిని భజించి ఎల్లప్పుడూ హృదయంలో ధ్యానం ఉంచుకొనేవాని కార్యాలన్నీ శుభంగా హనుమంతునిచే సిద్ధిస్తాయి.',
      },
    },
    'ganesh-aarti': {
      summary: 'దాదాపు ప్రతి పూజ ప్రారంభంలో, గణేశ చతుర్థినాడు పాడే హిందీ గణేశ హారతి. ఏకదంతుడు, నాలుగు చేతుల వాడు, నుదుట సింధూరం ధరించి ఎలుకపై స్వారీ చేసే దేవుని స్తుతించి, తాంబూలం, పండ్లు, మేవా, లడ్డూల నైవేద్యాన్ని చెప్పి, ఆయన గుడ్డివారికి కన్ను, రోగికి ఆరోగ్య శరీరం, సంతానం లేనివారికి సంతానం, పేదవారికి ధనం ఇస్తాడని చెబుతుంది.',
      verses: {
        '0.0': 'గణేశునికి జయం, గణేశునికి జయం, దేవుడు గణేశునికి జయం; ఆయన తల్లి పార్వతి, తండ్రి మహాదేవుడు.',
        '1.0': 'ఏకదంతుడు, దయామయుడు, నాలుగు భుజాలు కలవాడు; నుదుటిపై సింధూరం శోభిస్తుంది, ఎలుక ఆయన వాహనం.',
        '1.1': 'తాంబూలం సమర్పిస్తారు, పండ్లు సమర్పిస్తారు, మేవా కూడా సమర్పిస్తారు; లడ్డూల నైవేద్యం పెడతారు, సాధువులు సేవ చేస్తారు.',
        '1.2': 'ఆయన గుడ్డివారికి కన్నులు, కుష్ఠురోగులకు ఆరోగ్య దేహం, సంతానం లేనివారికి సంతానం, పేదవారికి ధనం ఇస్తాడు.',
        '1.3': '‘సూర్’ శ్యామ్ నీ శరణు వచ్చాడు; అతని సేవను సఫలం చేయి. ఆయన తల్లి పార్వతి, తండ్రి మహాదేవుడు.',
        '2.0': 'దీనుల మానం కాపాడు, శంభుపుత్రా; కోరికలు తీర్చు, నేను నీకు అంకితమవుతాను.',
      },
    },
    'lakshmi-aarti': {
      summary: 'శుక్రవారం, దీపావళి లక్ష్మీపూజలో పాడే హిందీ లక్ష్మీ హారతి. విష్ణువు, బ్రహ్మ రాత్రింబవళ్ళు సేవించే తల్లిగా స్వాగతించి, ఉమ, రమ, బ్రాహ్మణిగా స్తుతించి; సుఖసంపదలనిచ్చేది, క్షీరసాగర పుత్రి, ఆమె లేనిదే యజ్ఞం, వస్త్రం, అన్నం, పద్నాలుగు రత్నాలు ఏవీ లేవని చెబుతూ, పాడేవారికి ఆనందం, పాపవిముక్తి హామీ ఇస్తుంది.',
      verses: {
        '0.0': 'ఓం, లక్ష్మీ మాతకు జయం, అమ్మ లక్ష్మికి జయం; నిన్ను రేయింబవళ్ళు హరి, విష్ణువు, విధాత బ్రహ్మ సేవిస్తారు.',
        '1.0': 'ఉమ, రమ, బ్రాహ్మణి రూపాల్లో నీవే జగన్మాతవు; సూర్యచంద్రులు నిన్ను ధ్యానిస్తారు, నారద మహర్షి నిన్ను గానం చేస్తాడు.',
        '1.1': 'దుర్గా రూపంలో నిర్మలవు, సుఖసంపదలనిచ్చేదానివి; నిన్ను ధ్యానించేవారు ఋద్ధిసిద్ధులను, ధనాన్ని పొందుతారు.',
        '1.2': 'నీవు పాతాళంలో కూడా నివసించేదానివి, నీవే శుభాలనిచ్చేదానివి; కర్మ ప్రభావాన్ని వెలిగించేదానివి, సంసార సాగరం నుండి రక్షించేదానివి.',
        '1.3': 'నీవు ఏ ఇంట్లో ఉంటావో అక్కడికి సద్గుణాలన్నీ వస్తాయి; అన్నీ సాధ్యమవుతాయి, మనసు భయపడదు.',
        '1.4': 'నీవు లేనిదే యజ్ఞాలు జరగవు, ఎవరికీ వస్త్రం దొరకదు; అన్నపానాల వైభవమంతా నీ వల్లనే వస్తుంది.',
        '1.5': 'నీవు శుభగుణాల సుందర మందిరానివి, క్షీరసాగరంలో జన్మించినదానివి; నీవు లేనిదే పద్నాలుగు రత్నాలను ఎవరూ పొందలేరు.',
        '1.6': 'మహాలక్ష్మి ఈ హారతిని పాడేవారి హృదయంలో ఆనందం నిండుతుంది, పాపం తొలగిపోతుంది.',
      },
    },
    'shiv-aarti': {
      summary: 'సోమవారం, ప్రదోషం, మహాశివరాత్రినాడు పాడే శివుని హిందీ హారతి. ఆయనను ఓంకారంగా, బ్రహ్మ విష్ణు సదాశివుల ఏకరూపంగా స్వాగతించి, ఆయన ఒకటి, నాలుగు, ఐదు ముఖాలు, రుద్రాక్ష ముండమాలలు, పులిచర్మం, త్రిశూలం, చంద్రరేఖను వర్ణించి, జటలోని గంగ, కైలాసం, కాశి, పాడేవారికి ఫలశ్రుతితో ముగుస్తుంది. అనేక ప్రతులలో చేర్చిన నాలుగు పద్యాలు ప్రత్యేక విభాగంలో ఉన్నాయి.',
      verses: {
        '0.0': 'ఓం, ఓంకార స్వరూపుడైన శివునికి జయం; నా స్వామి ఓంకార శివునికి జయం. బ్రహ్మ, విష్ణు, సదాశివుడు; అర్ధాంగంలో తన శక్తిని ధరించినవాడు.',
        '1.0': 'ఒక ముఖం, నాలుగు ముఖాలు, ఐదు ముఖాలతో ప్రకాశిస్తాడు; హంస, గరుడ, వృషభ వాహనాలపై శోభిస్తాడు.',
        '1.1': 'రెండు చేతులు, నాలుగు చేతులు, పది చేతులతో ఎంతో శోభిస్తాడు; త్రిగుణ రూపాన్ని చూసి మూడు లోకాల జనులు మోహితులవుతారు.',
        '1.2': 'రుద్రాక్షమాల, వనమాల, ముండమాల ధరిస్తాడు; చందనం, కస్తూరి శోభిస్తాయి, నుదుటిపై చంద్రుని ధరించాడు.',
        '1.3': 'తెల్లని వస్త్రం, పసుపు వస్త్రం, దేహంపై పులిచర్మం; సనకాది మునులు, గరుడాదులు, భూతగణాలు ఆయన వెంట ఉంటారు.',
        '1.4': 'చేతుల్లో కమండలం, చక్రం, త్రిశూలం ధరించినవాడు; సుఖాన్నిచ్చేవాడు, దుఃఖాన్ని హరించేవాడు, జగత్తును పాలించేవాడు.',
        '1.5': 'బ్రహ్మ, విష్ణు, సదాశివులను వేరుగా భావించడం అవివేకం; ప్రణవాక్షరం ఓంలో ఈ ముగ్గురూ ఒక్కటిగా శోభిస్తారు.',
        '2.0': 'లక్ష్మి, సావిత్రి పార్వతితో కలిసి ఉన్నారు; పార్వతి ఆయన అర్ధాంగి, శివుని జటల నుండి గంగ ప్రవహిస్తుంది.',
        '2.1': 'పర్వతాలు పార్వతికి శోభ, శంకరుడు కైలాసంలో ఉంటాడు; గంజాయి, ఉమ్మెత్త ఆయన ఆహారం, భస్మంలో నివాసం.',
        '2.2': 'జటలో గంగ ప్రవహిస్తుంది, మెడలో ముండమాల ఉంది; శేషనాగు చుట్టుకొని ఉంది, జింక చర్మం కప్పుకున్నాడు.',
        '2.3': 'కాశీలో విశ్వనాథుడిగా కొలువై ఉంటాడు, బ్రహ్మచారి నంది తోడుగా; ప్రతిరోజూ లేచి దర్శనం పొందుతారు, ఆయన మహిమ ఎంతో గొప్పది.',
        '3.0': 'త్రిగుణాల ప్రభువు ఈ హారతిని ఎవరు పాడుతారో వారు సుఖసంపదలు పొందుతారని శివానంద స్వామి అంటున్నారు.',
      },
    },
    'kunj-bihari-aarti': {
      summary: 'జన్మాష్టమినాడు, కృష్ణ ఆలయాల్లో పాడే, కుంజాల్లో విహరించే కృష్ణుని హిందీ హారతి. నాలుగు పద్యాల్లో: రాధతో వైజయంతీ మాల, వేణువు, కుండలాలు గల శ్యామ రూపం; దేవతలు దర్శనానికి ఆరాటపడే బంగారు నెమలి కిరీటం; ఆయన పాదాల నుండి ఉద్భవించి శివుని జటలో నిలిచిన గంగ; గోపాలురు పాడే, ఆయన దీనుల మొర వినే వృందావన చంద్రికా తీరాలు.',
      verses: {
        '0.0': 'కుంజబిహారికి హారతి; గిరిని ఎత్తిన శ్రీ కృష్ణ మురారికి హారతి.',
        '1.0': 'మెడలో వైజయంతీ మాల, మధుర బాలుడు వేణువు వాయిస్తాడు; చెవులలో కుండలాలు మెరుస్తాయి, నందుని ఆనందం నందలాలా. ఆకాశంలా నల్లని దేహకాంతి, సఖీ, రాధిక పక్కన మెరుస్తోంది; లతల మధ్య వనమాలి నిలిచాడు, తుమ్మెదల వంటి ముంగురులు, నుదుట కస్తూరి తిలకం, చంద్రుని వంటి కాంతి: ప్రియమైన శ్యామునితో మనోహర రూపం, శ్రీ గిరిధర కృష్ణ మురారి.',
        '1.1': 'బంగారు నెమలి కిరీటం మెరుస్తుంది, దేవతలు దర్శనానికి తపిస్తారు; ఆకాశం నుండి పూల రాశి కురుస్తుంది. మురచంగ మోగుతుంది, మధుర మృదంగం, గోపికలతో కలిసి: గోపకుమారికల అసమాన ప్రేమ, శ్రీ గిరిధర కృష్ణ మురారికి.',
        '1.2': 'గంగ ఎక్కడ నుండి ప్రకటమైందో, మనసులోని సకల బాధలను హరించే శ్రీ గంగ, స్మరణతో మోహం తొలగుతుంది; ఆమె శివుని శిరస్సున, జటల మధ్య నివసించి పాప కల్మషాన్ని కడుగుతుంది: అటువంటిది శ్రీ వనమాలి పాదాల శోభ, శ్రీ గిరిధర కృష్ణ మురారిది.',
        '1.3': 'తీరంలోని ప్రకాశవంతమైన ధూళి మెరుస్తోంది, వృందావనంలో వేణువు మోగుతోంది; నాలుగు వైపులా గోపికలు, గోపాలురు, గోవులు. మృదువుగా, మందంగా నవ్వుతాడు, చంద్రిక, చంద్రుడు, సంసార పాశాలు తెగుతాయి: దీనుల, దుఃఖితుల మొర వినండి, శ్రీ గిరిధర కృష్ణ మురారి.',
      },
    },
  },
};
